pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it is often harder to fill later. We penalize small residuals exponentially.
    if post > 0.0 && post < 10.0 {
        score += 20.0 / (post + 1.0);
    }

    // Lookahead logic: if next_item_size is large, we prefer bins that can accommodate it.
    // If post_residual is too small to fit the next item, we add a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding for opening new bins:
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is the score for opening a new bin.
        // We increase the cost of a new bin as we approach the end of the stream.
        score = 25.0 + (35.0 * progress);
    } else {
        // For existing bins, if it's the last chance (fitting_bins_count == 1),
        // we reward picking it to avoid opening a new bin later.
        if fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Penalize high mean_residual to encourage consolidation.
    score += (mean_residual - post) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is in the "danger zone" (1..19), heavily penalize unless it's a perfect fit.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20.0 - post_residual as f64) * 2.5;
    }

    // Lookahead logic: if we have a next item, check if it fits in the current post_residual.
    // Reward bins that can accommodate the next item (Best-Fit-Lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize if we are blocking the next item from fitting, 
            // but only if there are other bins available.
            score += 15.0 / (fitting_bins_count as f64 + 1.0);
        }
    }

    // Harmonic Class Logic: Prefer bins that leave residuals which are multiples of 25.
    // This encourages stacking items to fill the bin exactly (e.g., 25+25+25+25).
    let rem_mod = post_residual % 25;
    score += rem_mod as f64 * 0.4;

    // Global state awareness:
    // If the bin is new (bin_residual == bin_capacity), penalize opening it 
    // unless we have no other good options (fitting_bins_count is low).
    if bin_residual == bin_capacity {
        score += 35.0 - (open_bins_count as f64 * 0.5);
    }

    // Encourage density: penalize bins that deviate significantly from the mean residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Final scaling for stream progression: towards the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual, so smaller is better.

    // 2. Lookahead Synergy: If the next item fits perfectly in this bin's post_residual,
    // we heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap).powf(1.5);
    }

    // 3. Last Chance Logic: If this is the only bin that fits the item, 
    // discourage using it if the post_residual creates "dead space" (e.g., < 10).
    if fitting_bins_count == 1 && post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 4. Global State Balancing: Encourage using bins that are already "less full" 
    // if we are early in the stream, or prioritize tighter bins late in the stream.
    let progress = step_index as f64 / total_items as f64;
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * (1.0 - progress);

    // 5. New Bin Penalty: If this is a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty unless it's the only option or we are forced.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if others exist
            score += 85.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Neutralize if no other bins fit
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (tiny gaps that are hard to fill)
    // We penalize post_residuals that are too small to fit the smallest expected items (10-20 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Aggressive 2-step lookahead matching
    // If the next item fits perfectly into the post_residual, prioritize this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_diff = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough space for the next item
            score -= (100.0 - fit_diff * 2.0);
        } else {
            // Penalize if this placement prevents the next item from fitting in this bin
            score += 20.0;
        }
    }

    // 3. Balance usage across bins (Entropy reduction)
    // Penalize bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Thresholding for opening new bins
    // If we are forced to open a new bin (fitting_bins_count == 0), normalize score
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already very low
        // This prevents fragmented bin opening
        if mean_residual > 20.0 {
            score -= 30.0;
        } else {
            score += 40.0;
        }
    }

    // 5. Progression awareness
    // Be more conservative with new bins as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "fragmented" small residuals (Best-Fit principle)
    // We heavily penalize residuals that are too small to fit common items (e.g., < 15).
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead optimization
    // If the next item exists, penalize placements that leave too little room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty if we block the next item from fitting in this bin.
            score += 60.0;
        } else {
            // Reward if we leave just enough room for the next item (tight packing).
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 / (1.0 + slack as f64));
        }
    }

    // 3. Global state balancing
    // If we have many open bins, prioritize closing them (Best-Fit).
    // If we are near the end of the stream, be more aggressive with space utilization.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * density_factor * progress;
    }

    // 4. New Bin Logic
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless all other options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 55.0;

        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -1000.0;
        } else {
            // Make new bin increasingly attractive as the stream progresses 
            // if current bins are very fragmented (high mean_residual).
            score += mean_residual * 0.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. Minimizing this is the Best Fit objective.
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // If the post_residual is too small to fit common items (effectively < 10), 
    // it becomes a liability. We penalize small residuals quadratically.
    if post_res < 15.0 {
        score += (15.0 - post_res).powi(2) * 0.5;
    }

    // Lookahead coupling: If the next item is large, we want to prioritize bins that 
    // can still accommodate it. If this bin cannot fit the next item, penalize it 
    // proportionally to the progression of the stream.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * (1.0 + progress);
    }

    // Global state awareness: 
    // If we have many open bins, we should be more aggressive about packing tightly.
    // If we have very few, we should be more willing to open a new bin if the fit is poor.
    let bin_pressure = open_bins_count as f64 / (10.0 + progress * 50.0);
    score += bin_pressure * post_res;

    // New bin logic:
    // When bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    // We normalize this cost against the mean_residual of existing bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is a last resort. 
        // We set the base "new bin" score to be higher than a tight fit, 
        // but lower than a very poor fit.
        score = 45.0 + (progress * 20.0);

        // If we are nearing the end of the stream, opening a new bin is increasingly costly.
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily in early stages, 
    // but become more aggressive as we reach the end of the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 200.0 + 50.0
    } else {
        0.0
    };

    // Calculate "tightness" of the fit.
    // Smaller post_residual is generally better (Best Fit).
    // We use an exponential weight to prioritize near-zero residuals.
    let fit_score = (post * post) / (bin_capacity as f64);

    // Lookahead logic: if the next item is large, we want to reserve space in open bins.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to keep the bin available for the upcoming larger item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Global state awareness: if we have many bins open, favor filling existing ones 
    // to increase packing density (mean_residual reduction).
    let density_pressure = (mean_residual - post) * (open_bins_count as f64).sqrt();

    // Final score: Lower is better.
    // We balance the immediate fit, the lookahead pressure, and the global density.
    fit_score + new_bin_penalty + lookahead_penalty + density_pressure
}

