pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it stays as the base.

    // 2. Harmonic/Modulo penalty: penalize residuals that are small but unusable (e.g., 1-9)
    // if next_item_size is large, a small residual is a "death trap".
    if post_residual < next_item_size && next_item_size > 0 {
        score += 150.0; // Heavy penalty for creating a bin that cannot fit the next item
    }

    // 3. New Bin Threshold: if we are forced to open a new bin, make it expensive
    // unless the current open bins have very poor space utilization.
    if bin_residual == bin_capacity {
        score += 40.0; // Base cost to open a new bin
        // If current bins are mostly full, opening a new one is more acceptable
        if mean_residual < 25.0 {
            score -= 15.0; 
        }
    }

    // 4. Fitting Bin Scarcity: if this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: as we approach the end of the stream, 
    // be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Harmonic refinement: favor bins that leave a residual which is a multiple 
    // of common item sizes (e.g., leaving 20 or 25 is better than leaving 13).
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base post_residual (Best Fit strategy baseline)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (small residuals that are hard to fill)
    // We heavily penalize residuals that are smaller than the smallest typical item (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Harmonic Class Logic: Reward placements that leave residuals which are multiples of 
    // common item sizes or fractions of capacity, facilitating future packing.
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to prioritize 'Perfect Fit' pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Global state awareness: If we are in the later stages of the stream, 
    // force tighter packing by penalizing large open bin counts.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // Boundary condition: If this is the only bin that can fit the item, 
    // we want to ensure it's not penalized too harshly unless it's truly terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 15.0;
    }

    // New Bin Candidate logic: 
    // If bin_residual == bin_capacity, this is a new bin. 
    // Increase its score (penalty) to encourage packing into existing bins 
    // unless the 'open_bins_count' is already high (diminishing returns).
    if bin_residual == bin_capacity {
        score += 35.0 - (open_bins_count as f64 * 0.5);
    }

    // Penalty for deviating from the mean_residual (maintains balanced bin fill levels)
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" that cannot fit common small item sizes (e.g., < 20)
    if post_residual < 20 && post_residual > 0 {
        score += 45.0;
    }

    // Harmonic preference: Reward residuals that are multiples of 25 (e.g., 0, 25, 50, 75)
    // This creates "bins of convenience" for future packing
    let mod_residual = post_residual % 25;
    score += (mod_residual as f64) * 0.8;

    // Lookahead logic: If the next item fits into this post_residual, prioritize this bin heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
    }

    // Balance the number of open bins: discourage opening new bins unless the fit is excellent
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins already, penalize opening a new one further
        score += (open_bins_count as f64) * 2.0;
    }

    // If this is the last chance to fit the item in an existing bin, reward it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Progression awareness: As the stream nears the end, be more aggressive with packing efficiency
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": post-residual gaps between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid leaving small post_residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // 3. Pressure management: Discourage opening new bins unless the current fit is very poor.
    // If bin_residual == bin_capacity, we are evaluating a "New Bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open if empty
        } else {
            // Only open new if fitting_bins are too tight to accommodate future items effectively.
            score = 25.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward utilizing existing bins, especially those with larger residuals (Best Fit).
        // Heavily penalize fitting into bins that result in "orphaned" small space.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Progress dependency: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We favor bins where the remaining space is small, but not so small it becomes useless.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Matching: Reward bins where the post_residual can fit the next_item_size.
    // This is the core of the aggressive 2-step lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for the next item: massive reward.
            score -= (bin_capacity - post_residual + next_item_size) as f64 * 2.0;
        } else {
            // Penalty for stranding the next item if this bin is our only option.
            if fitting_bins_count == 1 {
                score += 50.0;
            }
        }
    }

    // 3. Fragmentation Avoidance: If post_residual is too small to be useful (e.g., < 10),
    // it's often better to have left it slightly larger or empty, unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
