}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Harmonic Class logic: Reward post_residuals that are multiples of common item sizes
    // Modulo 20 and 25 are common in bin packing, creating "harmonic" gaps.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

