    // If bin_residual == bin_capacity, this is a new bin. 
    // Penalty is high to discourage opening a new bin unless existing bins are all "bad" fits.
    if bin_residual == bin_capacity {
        score = 35.0 + (mean_residual * 0.2);
    }

