    let mut score = post_residual as f64;

    // Penalty for creating 'orphaned' small space (unusable dead space)
    // If post_residual is small but > 0, it's often worse than 0 (perfect fit)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if next_item fits in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state: if we have many bins open, try to pack tighter to empty some
    // If we have very few bins open, be more aggressive with opening new ones to keep options open
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    } else {
