            score -= (100.0 - (post_residual - next_item_size) as f64).sqrt() * 2.0;
        } else {
            // Penalize creating a bin that cannot fit the next item if possible
            score += 20.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the existing fit is truly terrible.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite high (bins are empty)
        // or if we are at the very end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 - (mean_residual * 0.3) + (progress * 10.0);
    } else {
        // 4. Fitting Pressure: If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 5. Harmonic Class Packing: Favor bins where residual is a multiple of larger item sizes (e.g., 20, 25, 33).
        // This keeps space "open" for standard item classes.
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance (penalizing post_residual in unusable small gaps)
    // coupled with open_bins_count pressure.

    let mut score = post_residual as f64;

    // 1. Penalize unusable gaps: If post_residual is small (e.g., < 10), it's likely dead space.
    // We penalize this heavily because items range from 10-80.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead optimization: If the next item is large, avoid leaving a small residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin if other options exist.
    // If this is a new bin (bin_residual == bin_capacity), increase score unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // New bin is necessary
            score -= 10.0;
        }
    }

    // 4. Tight fit reward: Favor bins that leave very little space (Best Fit variant).
    // We favor post_residual values that are close to 0.
    score += (post_residual as f64) * 0.5;

    // 5. Global state normalization: Penalize increasing the number of active bins too early in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins where the remaining space is small.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Matching: If post_residual is close to next_item_size, we favor it.
    // This creates "perfect" pairs in bins.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.2;
    }

    // 3. Mean Residual Calibration: Avoid bins that deviate significantly from the average.
    // This helps in keeping the distribution of space uniform across open bins.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.3;

    // 4. New Bin Thresholding: 
    // If the bin is new, apply a heavy penalty to discourage unnecessary bin creation.
    // However, if the current item is very large or fitting_bins_count is low, 
    // allow the new bin to be more competitive.
    if bin_residual == bin_capacity {
        score += 45.0; 
