            score -= 30.0;
        }
    }

    // 5. Fragmentation Avoidance: Penalize post_residual ranges that are too small to fit 
    // common small items (e.g., < 10) but too large to be considered "full".
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 6. Progression Weighting: As we approach the end of the stream, 
    // be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
