    }

    // 6. Distribution Smoothing: Account for the mean residual to keep bin occupancy balanced.
    // If this bin is much fuller than the average, it is a good candidate.
    let residual_delta = (bin_residual as f64) - mean_residual;
    score += residual_delta * 0.5;

