    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: If the next item fits into this post_residual, 
    // significantly lower the score to prioritize this bin.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 50.0 * (1.0 - progress);
    }

    // Dynamic constraint: If this is the last fitting bin, we should be more 
    // cautious about opening a new bin. We make the current bin more attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New Bin Penalty: If this is a new bin (residual == capacity), add a heavy 
    // penalty that scales with the progress of the stream to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 30.0);
    }

    // Influence of existing bin density: If the mean residual is high, 
    // we are wasting space globally; penalize opening new bins further.
    score += mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residual space that cannot fit common item sizes.
    // If post_residual is small (e.g., < 10), it's "dead space".
    if post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fitting Pressure: If this is the only bin that can fit, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 4. Harmonic Alignment: Reward bins that align with capacity fractions (e.g., 1/2, 1/3, 1/4).
    // This helps group items of similar sizes together.
    let capacity_fraction = (post_residual as f64 / bin_capacity as f64) * 10.0;
    score += (capacity_fraction % 2.0) * 5.0;

    // 5. New Bin Threshold: If this is an empty bin, penalize it based on how many bins are already open.
    // We only want to open a new bin if the existing bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // As the stream progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space': gaps smaller than the minimum likely item size (10)
    // are highly undesirable as they rarely get filled.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If we are forced to open a new bin (fitting_bins_count == 0), 
    // prioritize keeping the bin_residual high to accommodate larger future items.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Lookahead logic: If a future item exists, penalize placements that create 
    // a post_residual that is too small for the next item, unless it's a perfect fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Global pressure: If we have many open bins, we must aggressively prioritize 
    // filling them rather than opening new ones, even if the fit is suboptimal.
    let fill_ratio = 1.0 - (mean_residual / bin_capacity as f64);
    if open_bins_count > 5 {
        score -= fill_ratio * 20.0;
    }

    // Reward perfect fits (Best Fit decreasing logic)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize opening a new bin if an existing bin could take the item reasonably well.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (too small for most items)
    // If post_residual is in the 1-9 range, it's highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead matching (Best Fit with Future Awareness)
    // If we have a next item, we want the current post_residual to be as close to it as possible
    // without going negative (which is already handled by the caller's bin selection logic).
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        // Reward placements where the remaining space is perfectly sized for the next item
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Global balance: Prefer bins that stay close to the mean residual
    // This helps keep bins packed at similar densities, preventing a single bin from being
    // left with a very small residual while others remain empty.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 4. Thresholding: Avoid opening a new bin if an existing bin can fit the item
    // effectively. Only open a new bin if the existing bins are "too crowded" or 
    // the current fit is extremely poor (large residual).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Penalize opening a new bin if we have plenty of open space elsewhere.
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // If we only have one bin that fits, we are forced to use it; reward this stability.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression scaling: Be more conservative as we near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post_residual (Best Fit), but we penalize 
    // "dead space" that is too small for any likely item (e.g., < 10).
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily unless we are near the end of the stream 
    // or the current bin-fitting options are extremely poor.
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
    }

    // 2. Lookahead logic: If the next item exists, penalize placements that 
    // make the current bin unable to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward placements that leave room for the next item
            score -= 10.0;
        }
