    // 3. Dynamic fitting pressure: If few bins can fit the current item, 
    // prioritize saving the "tightest" fit to prevent fragmenting the bin space.
    if fitting_bins_count > 0 {
        let fit_ratio = 1.0 / (fitting_bins_count as f64);
        score += fit_ratio * 10.0;
    }

    // 4. Global state coupling: If the mean residual of open bins is already high, 
    // we want to prioritize filling those bins rather than opening new ones.
    if !is_new_bin {
        score -= mean_residual * 0.2;
    }

    // 5. Final penalty for creating "sliver" space that is likely unusable 
    // (assuming most items > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We target a post_residual of 0 or a value that is likely to fit the next item.
    let sliver_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor larger post_residuals
    // if next_item_size is small, favor smaller post_residuals (packing efficiency)
    let lookahead_alignment = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -(post - next_item_size as f64).powf(0.5) * 5.0
        } else {
            (next_item_size as f64 - post).powf(1.5) * 2.0
        }
    } else {
        0.0
    };

    // Dynamic threshold: as we approach the end of the stream, prioritize 
    // filling existing bins more aggressively (minimizing open_bins_count).
    let completion_pressure = (open_bins_count as f64) * progress * 10.0;

    // Favor bins that have a post_residual close to the mean_residual of other bins
    // to keep the packing density consistent across the bin set.
    let consistency_score = (post - mean_residual).abs() * 0.5;

    // Base score: prioritize smaller post_residual (Best Fit)
    // Add penalties for creating slivers and misaligning with the next item.
    let mut score = post + sliver_penalty + lookahead_alignment + completion_pressure + consistency_score;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy 
    // "tax" that diminishes as the stream progresses and open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
    } else if fitting_bins_count == 1 {
        // If this is the only bin that fits the item, make it very attractive 
        // to avoid opening a new bin unnecessarily.
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

