        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead Coupling: If the next item is large and this bin can't fit it, 
    // prioritize leaving space in other bins.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // This bin is becoming a "fragment" that cannot accommodate the next item.
            score += 15.0;
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin residual is already much lower than the mean,
    // placing here helps balance the load.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We prioritize bins where the remaining space is small.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual,
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Reward small gaps after the next item is placed.
        score -= (100.0 - (gap as f64 * 2.0)).max(0.0);
    }

    // 3. Fragmentation Control: If this is the last chance for the current item,
    // we lower the barrier to accept a slightly worse fit to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 4. Mean Residual Alignment: Penalize bins that deviate significantly from 
    // the average state of the system to maintain uniform packing density.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Threshold: If considering a brand-new bin, apply a heavy penalty
    // unless the current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual of existing bins is already very low
            // or if we are near the end of the stream.
            score += 60.0 + (mean_residual * 0.5);
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
