        score += 40.0 * (1.0 - progress);

        // If we have many open bins with high residuals, penalize opening another
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 20.0;
        }
    } else {
        // If this is the only bin that fits, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Reward bins that align with the global mean residual to keep distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses
    // to force packing efficiency in later stages.
    let mut score = if is_new_bin {
        (1.0 - progress).powf(0.5) * 40.0 + 10.0
    } else {
        // Best Fit Decreasing logic: prioritize smaller post_residual.
        // We use a power transform to emphasize tight fits.
        post_res.powf(1.5)
