    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, but we apply a non-linear weight to reward tight packing.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Evaluate how well the post_residual accommodates the next item.
    // If post_residual is nearly a multiple of the next item size, we reward that bin.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward if next_item_size fits perfectly or leaves minimal slack
        if remainder < 5 {
