        }
        // Penalize if the next item cannot fit in the post_residual at all
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits the item, prioritize it heavily.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 4. Empty Bin Threshold: Manage when to open a new bin.
    // If we are opening a new bin (bin_residual == bin_capacity), add a cost based on current congestion.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins open with small residuals.
        // We only want to open a new bin if the mean_residual of existing bins is already small (tight).
        score += 60.0 + (mean_residual * 0.5);
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive about packing
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
