pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space" that is too small for future items.
    // If post_residual is < 10, it is likely wasted space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead coupling: If next_item_size is large, avoid bins that leave 
    // just enough space to be unusable for that large item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            score += (next - post) * 2.5;
        }
    }

    // Progression coupling: As we near the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    if res == cap {
        // Penalty for opening a new bin: increases as we approach the end of the stream.
        score += (open_bins_count as f64 * 2.0) * (1.0 + progress * 5.0);
    } else {
        // Favor bins that align with the mean usage of current bins to keep them balanced.
        let deviation = (res - mean_residual).abs();
        score += deviation * 0.5 * (1.0 - progress);
    }

    // Critical constraint: If this is the only bin that fits, heavily reward it.
    if fitting_bins_count == 1 && res != cap {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
