    // Critical constraint: If this is the only bin that fits the item, 
    // heavily reward selecting it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it stays in the score.

    // 2. Harmonic Class Logic:
    // If post_residual is small, it might be perfect, but if it's just slightly too large
    // for a future item, it's bad. Check if post_residual fits the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that create a "dead zone" where nothing can fit anymore
            if post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // 3. Density Balancing:
    // If we have many open bins, penalize opening a new one unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin fits, this is a necessary evil; adjust by progression
            score -= 10.0 * (step_index as f64 / total_items as f64);
        }
    }

    // 4. Harmonic Pressure:
    // If the residual is close to a fraction of the capacity (e.g., 50, 33, 25),
    // it is highly versatile. Reward residuals that align with common divisors.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 15.0;
    }

    // 5. Mean Residual Correction:
    // Avoid creating bins that are significantly worse than the current average.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small for any future item, 
    // it is highly undesirable (unusable sliver).
    // We penalize residuals < 10 (the minimum possible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many bins open,
    // but reward opening a new bin if the current bin is "almost full" and we 
    // want to preserve it for a better match later.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already
        score += (open_bins_count as f64) * 2.0;

        // If we are near the end of the stream, opening a new bin is very expensive
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    // 4. Fitting Bin Scarcity: If this is the ONLY bin that can fit the item, 
    // strongly incentivize choosing it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the 
    // average residual of open bins to keep bin states uniform (Load Balancing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

