    if bin_residual < bin_capacity && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 4. Mean Residual coupling: Penalize deviations from the average residual to maintain bin uniformity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Logic: If this is a new bin candidate, only choose it if the current bin would be highly inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite high (bins are empty)
