    let mut score = post_res.powf(1.5);

    // Penalty for leaving "dead space" (small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 heavily, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, avoid creating small residuals now.
    if next_item_size > 60 && post_residual < next_item_size {
        score += 40.0 * (1.0 - progress);
    }

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fit in existing
        // bins is exceptionally poor (indicated by high mean_residual).
        let open_bin_penalty = (open_bins_count as f64).powf(1.2) * 5.0;
        let efficiency_threshold = 20.0 * (1.0 - progress);
        score = 80.0 + open_bin_penalty - (mean_residual * 0.5) + efficiency_threshold;
    } else {
        // If it's an existing bin, favor bins that keep the mean_residual low
        // to maximize future packing flexibility.
        score -= (mean_residual - post_res) * 0.5;
    }

    // Final adjustment based on fitting constraints
    if fitting_bins_count == 1 && post_residual > 15 {
        // If this is the only bin that can fit the item, but it leaves a large gap,
        // penalize it slightly to see if opening a new bin might be better (if new bin score is lower).
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
