        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Discourage creating "unusable" gaps (e.g., 1-9 residual)
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Global state adjustment: if we have many open bins, penalize opening more
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We apply a non-linear penalty to small residuals that are likely to become "dead space"
    // based on the average size of current bins.
    let mut score = post * (1.0 + 0.5 * (mean_residual / bin_capacity as f64));

    // Penalty for creating a bin with very little space left if it's not the end of the stream
    if post < 10.0 && post > 0.0 {
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, penalize small post_residuals 
    // that won't accommodate the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full)
        // or if we have very few fitting options.
        let openness = (open_bins_count as f64).sqrt();
        score = 45.0 + (mean_residual * 0.5) - (openness * 2.0);

        // As the stream nears completion, heavily penalize opening new bins
        score += progress * 50.0;
    } else {
        // Reward bins that are "tightly packed" relative to the mean
        if post < mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (fragments)
    // We prefer post_residuals that are either 0 (perfect fit) or large enough to host future items.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 45.0; // Heavy penalty for "sliver" waste
        } else if post_residual < 30 {
            score += 15.0; // Moderate penalty for medium waste
        }
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if the post_residual is a "tight" fit for the next item
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }

    // 3. Bin Efficiency: Discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the mean residual of existing bins is already very low
        // or if we have no fitting bins.
        if fitting_bins_count > 0 {
            score += 60.0; // Strongly discourage opening new bin if space exists
        } else {
            score -= 10.0; // Neutral baseline for mandatory new bin
        }
    }

    // 4. Harmonic Alignment: Reward bins that keep the mean residual balanced
    // We want the bin we choose to bring the residual closer to the global mean
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize space consolidation
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (small gaps that are unlikely to fit any future items)
    // Gaps between 1 and 9 are extremely difficult to fill given the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
