    // This helps pack items into bins that are already partially filled.
    if post_residual < (mean_residual as u32) {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // 5. Progression Scaling: As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

