        score += diff * 1.5;
    }

    // 3. Prevent fragmentation: Penalize creating "unusable" small gaps (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean-residual balancing: If post_residual is significantly better than 
    // the current mean_residual, bias towards it to keep bins tightly packed.
    if (post_residual as f64) < mean_residual {
