    }

    // 5. New-bin threshold control: Only open a new bin if the current fit is terrible.
    // If we have open bins, heavily penalize opening a new one unless space is extremely scarce.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; 
    }

    // 6. Final progression adjustment: As the stream nears the end, become more 
    // aggressive about closing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic Strategy:
    // 1. Prioritize Best-Fit behavior (post_residual minimization).
    // 2. Penalize "orphaned" residuals (post_residual values too small to fit common items).
    // 3. Use lookahead to avoid fragmenting bins if the next item is large.
    // 4. Force new bin opening if current open bins are becoming too fragmented (high mean_residual).

    let mut score = post_residual as f64;

    // Penalty for creating "slivers": space that is too small for most items (10-20)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: If the next item is large and won't fit in this post_residual, 
    // penalize this bin to keep it open for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already poor
        // or if we are forced because nothing else fits well.
        if mean_residual < 25.0 && fitting_bins_count > 0 {
            score += 60.0; 
        } else {
            score += 15.0;
        }
    }

    // If this is the last chance for this item, reward it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Progression scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as stream progresses
    // to force consolidation in the latter half of the stream.
    let new_bin_penalty = if bin_residual == bin_capacity { 
        25.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Reward "Best Fit" logic: minimize post_residual, but heavily penalize values 
    // that result in "dead space" (small remainders that are unlikely to be filled).
    // The threshold for dead space is linked to the next_item_size if available.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        if next_item_size > 0 && post < next_item_size as f64 {
            30.0 / (post + 1.0)
        } else {
            15.0 - post
        }
    } else {
        0.0
    };

    // Influence of open bin count: if we have many open bins, prioritize filling 
    // existing bins with smaller residuals to close them out.
    let consolidation_pressure = (open_bins_count as f64) * (1.0 - progress);

    // Combine factors:
    // 1. post: Standard Best-Fit (lower is better).
    // 2. new_bin_penalty: Discourage new bins.
    // 3. dead_space_penalty: Avoid leaving tiny gaps.
    // 4. consolidation_pressure: Encourage packing into bins that are already nearly full.
    let score = post 
        + new_bin_penalty 
        + dead_space_penalty 
        - (consolidation_pressure * (residual / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
