        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 0.8;
    }

    // 3. Global Efficiency Balancing: If we are using many bins, prioritize filling 
    // existing ones over opening new ones (penalize opening new bins).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If other bins can fit this item, punish opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Residual Dispersion Penalty: Avoid creating bins that deviate significantly 
    // from the current mean_residual, as this keeps the bin states uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression Bias: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the trailing waste.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead reward: If next_item_size fits in the post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Penalty: Discourage opening a new bin unless the current fit is extremely poor
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is scaled by the mean utilization
        // We only open a new bin if the mean residual of existing bins is already tight (< 15)
        if mean_residual > 15.0 {
            score += 40.0;
        } else {
            score += 90.0;
        }
    }

    // 4. Tightness reward: Favor bins that are becoming "full" (low post_residual)
    // This pushes the algorithm toward Best-Fit Decreasing behavior
    if post_residual < 10 {
