    }

    // 5. Global State Awareness:
    // If we are nearing the end of the stream, prioritize packing tightly
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Last Chance logic:
    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Penalty for creating "islands" (bins with very awkward residuals)
    // Residuals between 1 and 9 are often "dead space" because min item size is 10
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

