    let mut score = post;

    // Penalize creating "dead space" that is likely too small for future items.
    // If post_residual is < 10 (the minimum item size), it's essentially dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 * (1.0 - (post / 10.0));
