        // Penalize opening new bins more as the stream progresses.
        score += 30.0 + (progress * 40.0);

        // If there are many fitting bins, it is almost always better to use one of them 
        // than to open a new bin.
        score += (fitting_bins_count as f64) * 20.0;
    } else {
        // For existing bins, reward configurations that align with the mean_residual
        // to keep bin utilization balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
