    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0; // Moderate reward for leaving "useful" small gaps
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual,
    // strongly prefer this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available.
    // As open_bins_count increases, the cost of opening a new one scales quadratically.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 2.0;
    }

    // 4. Fitting Constraint: If this is the last fitting bin, prioritize it to 
    // prevent forced new bin allocation, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin residual is significantly 
    // higher than the mean, prefer filling it to reduce bin variance.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

