    }

    // 3. Fragmentation Avoidance: If post_residual is too small to be useful (e.g., < 10),
    // it's often better to have left it slightly larger or empty, unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Mean Residual Balancing: Penalize bins that deviate significantly from the average 
    // fullness of currently open bins to keep the "bin landscape" uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // apply a dynamic cost based on progress to discourage opening new bins too early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
