    score += deviation * 0.2;

    // Last chance logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Dynamic horizon: As the stream nears completion, become more aggressive 
