    };

    // Calculate a "tightness" factor: we want to minimize post_residual, 
    // but we want to avoid creating "dead space" that is too small for future items.
    // A post_residual of 0 is ideal, but small remainders (1-9) are often worse than 0.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
