        // Bonus for tight fit (leaving very little space after next item)
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
    }

    // 3. Penalty for opening new bins prematurely:
    // If this is a new bin (residual == capacity), heavily penalize unless 
    // it's the only option or the current mean residual is already quite low.
    if bin_residual == bin_capacity {
        score += 85.0; // Base cost to open a new bin
        if fitting_bins_count > 0 {
            score += (open_bins_count as f64) * 5.0; // Penalty scales with existing bin count
        }
    }

    // 4. Mean Residual balancing:
    // If this bin's post_residual is significantly worse than the current mean, 
    // penalize it to force the algorithm to keep bins tightly packed.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression awareness:
    // As we approach the end of the stream, prioritize using open bins over new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin heavily, especially if there are bins that fit
        score = 85.0 + (fitting_bins_count as f64 * 15.0) + (progress * 20.0);
    } else {
        // Best Fit Decreasing logic: favor smaller post_residual
        // Penalize creating "dead zones" (small residuals that cannot fit common items)
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Lookahead: if the next item is large, avoid leaving a small residual now
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 25.0;
            } else {
                // Reward leaving space for the next item
                score -= 15.0;
            }
        }

        // Global pressure: if we have many bins open, try to pack tighter
        if (open_bins_count as f64) > (10.0 / (1.0 - progress + 0.1)) {
            score += 10.0;
        }

        // If this bin is the last chance for the current item, prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for common items (dead space).
    // If post_residual is small but not zero, it's often a "bad" fit.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next_item_size is large and we are creating a small gap, penalize.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 40.0 * (1.0 - (post / next_item_size as f64));
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // at filling existing bins to minimize the total count.
    // If we are late in the stream, heavily penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + (45.0 * progress);
    }

    // Encourage packing into bins that are already closer to the mean residual
    // to maintain a uniform distribution of fill levels across bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_diff;

    // Favor bins that have fewer alternatives if the fit is decent, 
    // to preserve "high-capacity" bins for larger future items.
    if fitting_bins_count > 0 {
        score -= (1.0 / fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

