    // If post_residual is in the range [1, 9], it's very hard to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic Class Logic: Favor bins where the post_residual is a multiple of 
    // likely future item sizes or aligns with capacity fractions.
    if next_item_size > 0 {
        // Reward placements where the remaining space is enough to accommodate the next item
        if post_residual >= next_item_size {
            score -= 20.0;
