            score += 15.0;
        }
    }

    // Efficiency bias: Reward using existing bins if they are already nearly full
    // but avoid over-filling if it traps a small residual.
    if fitting_bins_count > 0 {
        let usage_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= usage_ratio * 10.0;
    }

    // New bin threshold control: 
    // If this is a new bin (bin_residual == bin_capacity), increase cost 
    // unless the mean_residual of existing bins is already very low (highly fragmented).
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < 15.0 && open_bins_count > 2 {
            score += 20.0; // Discourage opening new bins if old ones are tight
        }
    }

    // Progression scaling: As we approach the end of the stream, prioritize 
    // packing density over future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
