        score += 35.0;

        // If many bins are already open, increase penalty to force consolidation
        score += (open_bins_count as f64) * 0.5;
    }

    // 6. Last Chance Logic: If this is the only bin that can fit the current item, 
    // reward selecting it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progression Scaling: As we approach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
