    // Penalize gaps that are too small for the minimum item size (assume min ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open bin pressure: Penalize opening a new bin if we have many bins open already.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on current open count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
