    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space; we want to minimize this (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, the penalty for opening a new bin should decrease 
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // Heuristic: If we have very few bins, we are less picky. If we have many, 
    // we want to prioritize closing bins or keeping residuals tight.
    // Penalty for leaving a bin with a very small, unusable gap (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead coupling: If the next item is large, avoid creating a post_residual 
    // that is smaller than the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Encourage filling bins that are already closer to the mean_residual of the system
    // to keep the "level" of bin fullness uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_diff;

    // Discourage opening a new bin if the current item fits well into an existing bin
    // (fitting_bins_count is the number of bins the item could fit into).
    if !is_new_bin && fitting_bins_count > 0 {
        score -= 5.0 / (fitting_bins_count as f64 + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prioritize bins that leave the least space (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If next_item_size fits in the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (100.0 - post_residual as f64) * 0.8;
    }

    // 3. Harmonic/Modulo pressure: Penalize residuals that are small but unusable 
    // for common item sizes (e.g., residuals < 10 are often dead space).
    if post_residual < 10 {
        score += 25.0; 
    }

    // 4. Thresholding: Avoid opening a new bin unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the item is very large or no other bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0; // Force opening if no other bin fits
        }
    }

    // 5. Dynamic density: Adjust based on the progression of the stream.
    // As we approach the end of the stream, prioritize packing tighter to close bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    // 6. Penalty for creating isolated bins:
    // If a bin has a very high residual, it's inefficient; penalize it.
    if post_residual > 60 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the smallest likely item (e.g., < 10)
    // are highly undesirable as they often remain empty forever.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Penalize opening a new bin if we have existing capacity.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    if bin_residual == bin_capacity {
        // Only consider opening a new bin if we are forced to (fitting_bins_count == 0)
        // or if our current open bins are already very full (mean_residual is low).
        if fitting_bins_count > 0 {
            score += 100.0 + (mean_residual * 2.0);
        }
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize this bin if it will likely be unable to fit the next item
            score += 20.0;
        }
    }

    // Dynamic pressure: as the stream progresses, favor packing tighter to close bins.
    score += (open_bins_count as f64) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Penalty: Penalize configurations that leave small, unusable slivers.
    // If we leave space between 1 and 9, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.8;
    }

    // 3. Mean Residual Balancing: Avoid deviating too far from the average state 
    // of the open bins to keep packing density uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: If this is an empty bin (new), add a bias based on
    // how many bins are already open. We prefer filling existing ones unless
    // the fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 1.5);
    } else {
        // Penalty for opening a new bin is high, but if fitting_bins_count is low,
        // we might be forced into a bad configuration; reward better fits.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progress Normalization: As we reach the end of the stream, prioritize 
    // closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
