    }

    // 2. Lookahead logic: penalize bins that cannot fit the next item if we have alternatives
    if next_item_size > 0 && post_residual < next_item_size {
        score += 35.0 * (1.0 - progress);
    }

    // 3. Global state awareness: discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available
            score += 60.0 + (open_bins_count as f64 * 0.5);
        } else {
            // Reward opening a new bin if no other options exist
            score -= 10.0;
        }
    }

    // 4. Balance the bins: penalize bins that deviate significantly from the mean residual
    // This promotes Best-Fit behavior by preferring bins that keep density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Dynamic time horizon: increase sensitivity to fit quality as stream nears completion
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

