    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // As the stream progresses, penalize opening new bins more heavily
        // to encourage packing into existing fragments.
        score += 45.0 * (1.0 + progress.powf(2.0));

        // If we have many open bins, penalize opening another one
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward placements that leave a residual close to the mean_residual of other bins
        // This encourages "uniform" bin states, reducing variance in packing density.
        let density_alignment = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * density_alignment;

        // Lookahead heuristic: If the next item is large, avoid leaving a tiny, unusable residual
        if next_item_size > 0 {
            if post_residual < next_item_size && post_residual > 0 {
                // Penalize "fragmentation" (creating a hole too small for the next item)
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }
    }

    // Edge case: If this is the only bin that can fit the item, prioritize it highly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Final non-linear scaling to favor tighter packing as the stream concludes
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic penalty: Heavily penalize post_residuals that are small but unusable (1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Next-item lookahead: If this bin fits the next item perfectly (or near-perfectly), prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        // Reward bins that leave exactly enough space for the next item
        score -= (100.0 / (fit_diff + 1.0));
    }

    // 4. Harmonic class thresholding:
    // If we have many open bins, we want to force consolidation into existing ones.
    // Increase cost of opening a new bin exponentially based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 5.0;
        // Further penalize opening a new bin if we are near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean residual balancing:
    // If this bin's residual is significantly lower than the average, it's a "tight" bin.
    // Tight bins are good, but if they are too tight, they become unusable.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Last-chance logic:
    // If this is the only bin that fits, we must take it (lower the score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
