        } else {
            score += 10.0; // Moderate cost to open new bin
        }
    }

    // 5. Balance the mean residual: Encourage using bins that are already "fuller"
    // to keep the mean_residual of open bins high (i.e., keep bins tight).
    if (bin_capacity - post_residual) < (bin_capacity as f64 - mean_residual) as u32 {
