    let mut score = post;

    // Penalty for "fragmentation": If post_residual is small but > 0, it's often wasted space.
    // We penalize values that are too small to fit common items (e.g., < 10).
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If we have a next item, try to leave enough space for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Penalize bins that cannot accommodate the next item if they could have otherwise.
            score += 20.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins over opening new ones.
    // If this is a new bin (bin_residual == bin_capacity), increase the cost significantly
    // as we approach the end of the stream to prevent unnecessary bin creation.
    if bin_residual == bin_capacity {
        score += 40.0 * progress;

        // If other bins can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Balancing: Avoid creating bins that are significantly below the mean residual of current bins,
    // which helps maintain a uniform fill rate across the system.
    let residual_diff = (post - mean_residual).abs();
    score += 5.0 * (residual_diff / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
