    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // Penalty for stranding the next item if it's large
            if next_item_size > 60 {
                score += 30.0;
            }
        }
    }

    // 3. Harmonic class logic: Favor bins that leave room for specific fractional capacities
    // This rewards "perfect" splits (e.g., leaving exactly 50 or 33 remaining)
    let residual_fraction = (post_residual as f64 / bin_capacity as f64) * 100.0;
    if (residual_fraction - 50.0).abs() < 5.0 {
        score -= 15.0;
    }

    // 4. Global state awareness:
    // If we have many open bins, prioritize filling existing ones (Best Fit style)
    // If we have very few, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress and current open count
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    } else {
        // Reward for using bins that bring the mean_residual closer to the item_size
        // This keeps packing density consistent
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= diff * 0.1;
    }

    // 5. Critical threshold: Avoid leaving a single bin that is "too full" to accept anything
    // if the next item is large.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
