    } else {
        // If this is the only bin that fits the current item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }

        // Encourage balancing: penalize bins that are significantly below the mean_residual
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the number of available fitting bins.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // significantly lower the score to prioritize this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Awareness: If we have many open bins, penalize opening a new one 
    // (where bin_residual == bin_capacity) to encourage consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0 * (1.0 - progress * 0.5);
    }

    // 4. Scarcity Logic: If this is the only bin that fits the current item (fitting_bins_count == 1),
    // and the post_residual is very small (potentially creating an unusable gap), 
    // provide a slight penalty to force better distribution in later steps.
    if fitting_bins_count == 1 && post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    // 5. Dynamic Thresholding: As we approach the end of the stream, 
    // prioritize filling existing bins more aggressively to avoid trailing new bins.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 6. Mean Residual Balancing: If the current bin's residual is significantly 
    // higher than the average, this placement is "wasting" more than the current strategy.
    if (bin_residual as f64) > mean_residual {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit principle)
    // We penalize high residuals exponentially to avoid fragmented space.
    let mut score = post.powf(1.5);

    // Dynamic penalty for opening new bins:
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize based on progress and current open bin efficiency.
        // We add a cost that increases as we approach the end of the stream (forcing consolidation).
        let open_bin_penalty = (open_bins_count as f64 * (1.0 + progress)) * 15.0;
        score += open_bin_penalty;
    } else {
        // Existing bin logic:
        // If this is the only bin that fits the item (fitting_bins_count == 1), 
        // we heavily favor it to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Lookahead coupling: If next_item_size is large, avoid leaving a very small residual
        // that will be unusable for the next item.
        if next_item_size > 0 {
            let next_item = next_item_size as f64;
            if post < next_item && post > 0.0 {
                // Penalize "dead zone" created by this placement
                score += (next_item - post) * 2.5;
            }
        }
    }

    // Secondary stabilization: Penalize deviation from the mean_residual of current bins
    // to maintain a uniform packing density across the bin set.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are too small to fit typical future items (< 10)
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes, increasing the probability of a perfect fit later.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily incentivize this bin (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Bonus for leaving exactly enough space for the next item
        if post_residual == next_item_size {
            score -= 30.0;
