    // Heuristic for new bin opening:
    // Only open a new bin if the current mean residual is already quite low,
    // suggesting we are struggling to pack efficiently, OR if we have very few options.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 25.0; // Discourage opening new bins if existing ones have space
        } else {
            score += 35.0; // Baseline cost of opening a new bin
        }
    }

    // Penalize fragmented bins: If this is the only bin that fits, we must take it,
    // but if many bins fit, we prefer the one that leaves the least waste.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely to become 
    // unusable "fragmentation" dead space. We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is very tight.
    // If this is a new bin, apply a significant penalty scaled by the current number of open bins.
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64 * 2.0);
