    }

    // 4. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // lower than the mean_residual of other bins, it's a tight fit, which is desirable.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Scarcity Constraint: If this is the only bin that can fit the item, 
    // lower the score to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals to keep bins tightly packed.
    // We normalize by capacity to weight the "wasted" space.
