    }

    // 3. Prevent fragmentation: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we heavily prioritize using it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 4. New Bin Thresholding: If evaluating a fresh empty bin (bin_residual == bin_capacity),
