    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening new bins if the average remaining space is still healthy.
            score = 55.0 + (mean_residual * 0.5);
        }
    } else {
        // 5. Balance the packing: slightly prefer bins that stay close to the global mean residual
        // to keep the bin distribution uniform.
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 6. Progressive tightening: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead and bin-utilization pressure.
    // We aim to minimize post_residual (Best Fit) while penalizing fragmentation.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Fragmentation Penalty: Penalize small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it is likely "dead space" because min item size is typically 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // 3. Global Pressure: If fitting_bins_count is low, we are running out of options.
    // Penalize opening a new bin (bin_residual == bin_capacity) unless existing bins are very full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual is already quite low (bins are full).
            score += 40.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
    } else {
        // Reward filling bins to capacity to maximize density.
        // As we reach the end of the stream, we become more aggressive in packing existing bins.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.1 * progress;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space. 
    // Smaller residual (tighter fit) is better (lower score).
    let mut score = post_res;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the range [1, 9] heavily, as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic preference: As we approach the end of the stream, prioritize 
    // filling existing bins (minimizing open_bins_count) to avoid leaving 
    // half-empty bins at the end.
    let fill_efficiency = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= progress * fill_efficiency * 20.0;

    // Heuristic for new bin threshold: 
    // If we are forced to create a new bin (fitting_bins_count == 0), 
    // the score is naturally higher. We modulate the "new bin" cost by 
    // the current mean_residual to prevent opening too many bins early.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have plenty of space elsewhere.
        score += 40.0 + (mean_residual * 0.5);

        // As the stream progresses, the penalty for opening a new bin decreases 
        // to allow for better packing density at the end.
        score -= progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones": if post_residual is small (1..9), it is often unfillable.
    if post_residual < 10 && post_residual > 0 {
