    // Harmonic class logic: prioritize bins that leave residuals which are multiples of common item sizes (e.g., 20, 25).
    // This minimizes fragmented space by aligning residuals with potential future items.
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

    // Threshold logic: If this is the only bin that fits the item, avoid opening a new bin at all costs.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New bin penalty: If we are considering a new bin (residual == capacity), penalize based on open bin pressure.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // If we are early in the stream, be more conservative about opening new bins.
        if (step_index as f64 / total_items as f64) < 0.3 {
