    // significantly reduce the score to prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect" fit for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap) * 2.5;
        } else {
            // Penalize bins that leave a "dead zone" too small for the next item.
            score += (next_item_size - post_residual) as f64 * 1.2;
