    // If this bin's post_residual is much smaller than the mean, it's a "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 4. Open Bin Constraints: If this is the only bin that fits the item, make it highly attractive
    // to avoid opening a new bin unnecessarily (unless the fit is truly atrocious).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

