        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward bins that keep the mean residual balanced
        // If this bin's post_residual is closer to the mean, it's a stable fit.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Critical Path: If this is the only bin that fits the item, 
    // prioritize it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Final adjustment: Prefer tighter fits (Best Fit heuristic base)
    // post_residual is already part of the score; we refine it to favor 
    // bins that are nearly full (post_residual near 0).
    score += (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
