    // We only open a new bin if the current 'best' fit is already very poor (post_residual < 10).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 60.0 + (100.0 * (1.0 - progress));
        } else {
            // If no other bin fits, the cost is just the capacity wasted
            score = bin_capacity as f64 - item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
