    // 3. Harmonic Lookahead: If next_item_size is known, favor bins where post_residual
    // can accommodate the next item (synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // Penalize bins that block the next item if other bins could fit it
            score += 15.0;
        }
    }

    // 4. Harmonic thresholding: favor bins that leave residuals which are multiples of 
    // common item sizes (20, 25, 33) to maximize packing density.
    if post_residual % 25 == 0 {
        score -= 10.0;
    } else if post_residual % 20 == 0 {
        score -= 8.0;
    }

    // 5. New Bin Control: If this is an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large
        // and doesn't fit well into the current open bins.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 60.0; 
        } else {
            score += 20.0;
        }
    }

    // 6. Global pressure: As we approach the end of the stream, prioritize closure 
    // of existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    // 7. Favor bins that keep the mean residual balanced
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to fit common items
    // If the remaining space is between 1 and 9, it is highly likely to be "dead space"
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on current usage
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Logic: If the next item exists, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.2;
        } else {
            // Penalize bins that block the next item from fitting here
            score += 15.0;
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if we have fitting options.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 2. Best-fit logic: Strongly prefer small post_residuals (tight packing).
    // We penalize larger post_residuals exponentially to avoid fragmentation.
    score += (post_residual as f64).powf(1.5);

    // 3. Lookahead Matching: If the next item fits perfectly into this post_residual,
    // we reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps after the next item is placed.
        score -= (100.0 - diff).powf(1.2);
    }

    // 4. Global balance: If this bin's post_residual is significantly worse 
    // than the current mean, penalize it to keep bin states uniform.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.5;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize 
    // filling bins to capacity over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 6. Last Chance Penalty: If this is the only bin that fits the current item,
    // we must take it, so we lower its score to ensure it is chosen.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 is ideal (Best Fit).
    // Strategy: Penalize "near-miss" gaps (e.g., 1-9) that are hard to fill.
    // Incorporate lookahead (next_item_size) to avoid splitting items that could pair well.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize small, unusable gaps (the "fragmentation trap")
    // If post_residual is small but > 0, it's often better to start a new bin 
    // unless the item fits perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead utility: If next_item_size exists, favor bins that leave enough 
    // room for it. If post_residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 3. Global state: If we have many open bins, penalize opening new ones.
    // If we have very few, be more aggressive with packing (Best Fit).
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // Only pick if fitting_bins_count is low or current mean_residual is very tight.
        score += 15.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.1);
    } else {
        // Reward utilizing existing bins.
        score -= (1.0 - progress) * 5.0;
    }

    // 4. Fitting constraint: If this is the only bin that fits the current item, 
    // highly reward choosing it to preserve future flexibility.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating "fragmented" space (small unusable residuals)
    // We penalize residuals that are smaller than the smallest possible item but larger than 0
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If we have a next item, favor bins that can accommodate both
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If the bin cannot fit the next item, penalize it slightly 
            // relative to how much space is left, increasing as we reach the end of the stream
            score += (1.0 - progress) * (next_item_size as f64 - post);
        }
    }

    // Dynamic thresholding: Near the end of the stream, prioritize closing bins (lower residual)
    // vs earlier where we might want to keep bins open to pack larger items
    score += (1.0 - progress) * (mean_residual - post).powi(2);

    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost 
    // to discourage opening new bins unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin is scaled by the difficulty of the current packing state
        score = 60.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    }

    // Boost score if this bin is the only one that fits (avoiding opening new bins unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

