    // 3. Lookahead Logic: If next_item_size is large, avoid bins that leave a small post_residual
    // that won't accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot take the next item
            score += 25.0;
        } else {
            // Reward creating a bin that can accommodate both current and next
            score -= 10.0;
        }
    }

    // 4. Harmonic thresholding: Favor residuals that align with common item sizes (divisibility)
    // Smaller bins (high residual) are generally less efficient; normalize by open_bins_count.
    score += (open_bins_count as f64) * 2.5;

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a new bin. 
    // Only open a new bin if the current fit is extremely poor (post_residual > 40).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can take it
            score += 50.0;
        }
        // Baseline cost for new bins
        score += 30.0;
    }

    // 6. Global progression: As we approach the end of the stream, be more aggressive
    // about filling existing bins to empty the set.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, but penalize "dead space"
