    let mut score = post_res;

    // Penalty for creating a bin that is almost empty (fragmentation), 
    // but scale this by progress to allow more flexibility early in the stream.
    // As the stream progresses, we become strictly more intolerant of small residuals.
    let fragmentation_penalty = (1.0 - (post_res / bin_capacity as f64)) * (1.0 - progress) * 20.0;
    score += fragmentation_penalty;

    // Lookahead logic: if the next item is large, prioritize keeping space open.
    // If post_residual is smaller than the next item, we penalize this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
