    // Encourage filling bins that are already partially full (reduce open_bins_count).
    // We favor bins where the current residual is already close to the mean residual.
    let deviation_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += deviation_from_mean * 0.1;

    // If this is the only bin that can fit the item, reward it to prevent opening a new bin
    // unless the fit is extremely poor (handled by the post_res penalty).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
