    }

    // New bin logic: if we are considering a new bin (bin_residual == bin_capacity),
    // apply a strong penalty that decreases as the stream progresses, 
    // effectively tightening the requirement to open a new bin over time.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    score
