    // Interaction between mean_residual and current post_residual to maintain balance.
    let balance_factor = (post - mean_residual).powi(2) * 0.05;

    // Combine terms:
    // 1. Base cost is the remaining capacity (standard Best-Fit).
    // 2. Add penalties for new bins and slivers.
    // 3. Subtract bonuses for lookahead efficiency.
    let score = post + new_bin_penalty + sliver_penalty + balance_factor + lookahead_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual is already preferred).
    // 2. Penalty for "Wasted Potential": if post_residual is small but not zero, it's often better to 
    //    have a larger residual that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placements that block the next item from fitting in this bin
            score += 45.0;
        } else {
            // Reward placements that keep the bin useful for the next item
            score -= 20.0;
        }
    }

    // 3. Harmonic class awareness: 
    // Small residuals (1..10) are often "dead space" if no items are that small.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // 4. Fitting constraints:
    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Global state normalization:
    // If we have many open bins, we are incentivized to pack tighter (Best-Fit).
    // If we have few, we can afford to be more selective to save space for future items.
    score += (open_bins_count as f64) * 0.5;

    // 6. New bin penalty: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 7. Progress-based scaling:
    // Toward the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit common items (10-20),
    // but large enough to waste space. We target a "Best Fit" behavior.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the new residual,
    // we reward this placement to keep the bin useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0; // Perfect packing reward
            } else if gap < 10 {
                score -= 10.0; // Good packing reward
            }
        }
    }

    // 3. Bin Count Pressure: As the stream progresses, increase the cost of opening new bins 
    // to force consolidation in the final stages of the sequence.
    let progression = step_index as f64 / total_items as f64;
    let new_bin_penalty = 15.0 * (1.0 + progression * 2.0);

    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        score += new_bin_penalty;

        // If we have many open bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 20.0;
        }
    } else {
        // This is an existing bin. Reward using bins that are already "half-full" or more
        // to keep the number of active bins low.
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization * 10.0;
    }

    // 4. Global Mean Constraint: Discourage bins that are significantly more empty than the average,
    // to prevent fragmentation across many bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
