    // 2. Lookahead Integration: If the next item is large, avoid bins that leave 
    // just enough space for the current item but not the next.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that create a perfect fit for the upcoming item
            if (post_residual as i32 - next_item_size as i32).abs() < 5 {
                score -= 20.0;
            }
        }
    }

    // 3. Global State Balancing: Use mean_residual to prevent "bin fragmentation"
    // If this bin is significantly emptier than the average, prioritize filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 15.0 * (bin_residual as f64 / mean_residual);
    }

    // 4. New Bin Logic: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a high base cost.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If we have many open bins, opening another is costly.
        score += open_bins_count as f64 * 2.0;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize clearing bins
    // to minimize the final count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 6. Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
