    // 2. Lookahead Synergy: Reward placements where post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: This bin can accommodate the next item perfectly.
            score -= (next_item_size as f64) * 1.5;
        } else {
            // Penalty: This bin will likely be useless for the next item.
            score += (bin_capacity - post_residual) as f64 * 0.5;
        }
    }

    // 3. Fragmentation Control: Penalize creating a bin that is "too empty" compared to the mean.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += 20.0;
    }

    // 4. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (cost of fragmentation)
        // or if fitting_bins_count is very low, forcing a sub-optimal fit.
        if fitting_bins_count > 0 {
            score += 45.0; // Heavily discourage opening new bins if fit exists.
        } else {
            score -= 10.0; // Allow opening if no other options exist.
        }
    }

    // 5. Progression Bias: As stream nears end, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
