    // expected items (heuristic threshold 10), it is "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // we prioritize this bin heavily to avoid opening a new bin later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already open.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we have other bins that can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // 4. Tightness bias: Favor bins that are already "fuller" (lower residual)
        // to keep the number of open bins low.
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

