    // We favor bins that become very tight (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Lookahead: If next_item_size is large, avoid small post_residuals 
    // that effectively "trap" the bin (i.e., leaving 5-9 space when next item is 20).
    if next_item_size > 0 {
        if post_residual < next_item_size {
