    }

    // 3. Fragmentation Mitigation: If post_residual is in the "danger zone" (1..9),
    // it is unlikely to fit future items. Heavily penalize this unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Bin Economy: If this is a new bin (bin_residual == bin_capacity),
    // add a base cost to discourage opening it unless necessary.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    // 5. Density Balancing: If the current bin is significantly emptier than the average,
    // favor it to consolidate space (fill the emptiest bin first).
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // reduce the penalty to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
