    // 2. Lookahead matching: If the post_residual can fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Stronger reward if the fit is tight (Best-Fit principle for the lookahead)
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // 3. Pressure management: If we are late in the stream, favor utilizing existing bins 
    // more aggressively to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += 20.0 + (progress * 40.0);
    } else {
        // Reward for using existing bins, scaled by how much they deviate from the mean.
        // This encourages balancing the residuals across bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Critical threshold: If this is the last bin that can fit the item, 
    // heavily prioritize it to prevent unnecessary new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
