pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity (Best Fit strategy)
    let mut score = post_res;

    // Penalty for creating a "fragmented" bin (too small to fit typical future items)
    // We penalize small residuals that are below the expected item size (mean_residual).
    if post_res > 0.0 && post_res < mean_residual {
        score += (mean_residual - post_res).powf(1.5);
    }

    // Lookahead logic: If the next item is large, avoid leaving a small residual now.
    // If next_item_size > post_residual, we are effectively stranding space.
    if next_item_size > 0 {
        if (next_item_size as f64) > post_res {
            score += (next_item_size as f64 - post_res) * 1.2;
        }
    }

    // Dynamic pressure: As we approach the end of the stream, prioritize packing 
    // tightly to avoid opening new bins. 
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We reward taking the fit to prevent new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 - progress);
    }

    // Penalize opening a new bin (bin_residual == bin_capacity)
    // We increase the cost of opening a new bin as the stream progresses.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Non-linear coupling: Favor bins that keep the mean residual balanced
    // relative to the remaining capacity of other open bins.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
