        // If mean_residual is large, we should have used an existing bin.
        score += (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    }

    // 5. Scarcity adjustment: As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Last Chance logic: If this is the only bin that can fit the item, prioritize it heavily
