    // too small to fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Pressure management: If we have many open bins, prioritize filling them tightly.
    // If we have few open bins, we are more willing to open a new one (lower new bin penalty).
    let open_bin_penalty = (open_bins_count as f64).powf(1.2) * 2.0;

    // 4. Handle the "New Bin" case (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced if we have very few bins already.
        score = 85.0 + open_bin_penalty;
    } else {
        // Favor bins that are already partially full to keep the number of active bins low.
        // We subtract a reward based on how much the bin is already filled.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;

        // Penalize bins that are "almost" full but don't fit the current item well, 
        // to encourage packing into bins that create better future utility.
        if fitting_bins_count == 1 {
            score -= 5.0; // Reward choosing the "last chance" bin to prevent fragmenting.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "orphan" space that is too small for common items.
    // If post_residual is small but > 0, it's often a "dead zone".
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
    }

    // 2. Lookahead: Reward bins that can accommodate the next item perfectly (Best-Fit-Lookahead).
    // If next_item_size fits in the post_residual, drastically lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (50.0 - fit_gap * 0.5);
    }

    // 3. New Bin Logic: Discourage opening new bins unless the current options are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High base penalty for opening a new bin.
        score += 65.0;

        // If we have many open bins that already fit the item, opening a new one is inefficient.
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64);
        }
    }

    // 4. Density Balancing: Favor bins that stay near the mean residual to keep packing uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression weighting: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: prioritize filling existing bins even if it leaves small gaps.
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // 2. Penalty for creating "dead space": If post_residual is small but > 0, it's often 
    //    worse than hitting exactly 0.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 15.0; 
    }

    // 3. Lookahead logic: If the next item is large, prioritize keeping space open.
    // If we have a next_item, penalize current bin if it consumes space needed later.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 20.0;
        }
    }

    // 4. Global state management:
    // If this is a new bin (bin_residual == bin_capacity), only open if fitting_bins_count is low.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0; // Necessary to open new bin
        } else {
            // Heavily penalize opening a new bin if an existing bin could fit it.
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Dynamic horizon: As we approach the end of the stream, be more aggressive 
    // with filling existing bins to reduce total count.
    if progress > 0.8 {
        score -= (1.0 - mean_residual / bin_capacity as f64) * 10.0;
    }

    // 6. Balance penalty: Avoid bins that are significantly below the mean residual 
    // to keep the bin distribution uniform.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    // We penalize the new bin creation exponentially as the stream progresses,
    // as unused capacity becomes more expensive later in the sequence.
    let mut score = post_residual as f64;

    if is_new_bin {
        // New bin penalty: increases linearly with progress to force Best-Fit behavior
        // as we approach the end of the stream.
        score = 55.0 + (progress * 40.0);
    } else {
        // Interaction: Penalize bins that leave behind "sliver" residuals (1-9)
        // that are unlikely to be filled by future items.
        if post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }

        // Lookahead bias: If the next item fits into the current post_residual,
        // reward this placement to keep the bin useful.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (progress * 0.5));
        }

        // Penalty for creating a bin with a residual significantly lower than the mean.
        // This encourages leveling out residuals across open bins.
        if (post_residual as f64) < mean_residual {
            score += 5.0 * (mean_residual - post_residual as f64) / 100.0;
        }

        // If this is the last chance for the current item, reduce the penalty
        // to ensure the item is placed rather than creating a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "orphan" space (1-9) which is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Best-Fit Decreasing logic: penalize large residuals in currently open bins
    // to keep the bin occupancy high.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Lookahead: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly
        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // Harmonic Class Logic: penalize bins that leave behind awkward fractions of capacity
    // 100/3 = 33, 100/4 = 25, 100/5 = 20. These are "good" residual targets.
    let remainder = post_residual % 25;
    if remainder > 10 && remainder < 20 {
        score += 15.0;
    }

    // New Bin Penalty: If this is a new bin call (bin_residual == bin_capacity),
    // only choose it if the existing options are truly poor.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 45.0;

        // If we have many open bins that can fit the item, discourage new ones
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 10.0;
        }
    } else {
        // If we are placing in an existing bin, favor bins that are already "fuller"
        // to keep the number of open bins low (First-Fit Decreasing derivative)
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Progressive tightening: as we approach the end of the stream, 
    // prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit common items
    // If post_residual is in (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when current bins are sufficient.
    // If this is a new bin (bin_residual == bin_capacity), penalize based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (100.0 * (step_index as f64 / total_items as f64));
    }

    // 3. Lookahead synergy: Reward placing items that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping a bin "viable" for the next item
            score -= 20.0;
        } else if post_residual > 0 {
            // Penalty if we block the next item from fitting in this bin
            score += 15.0;
        }
    }

    // 4. Tightness reward: Favor Best-Fit behavior by rewarding smaller post_residuals
    // that are >= 10 (the minimum item size).
    if post_residual >= 10 {
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Fitting constraint: Strongly discourage leaving only one bin available if we can avoid it.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin: only do it if the fit is truly optimal.
    if bin_residual == bin_capacity {
        score += 25.0; 
    }

    // 2. Lookahead mechanism: If next_item_size is known, favor bins that leave space 
    // for it, or minimize the "wasted" gap if next_item_size doesn't fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit scenario: reward bins that can accommodate the next item.
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalty for stranding a small gap that cannot fit the next item.
            score += (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. Pressure management: If we are running out of items, be more aggressive.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 4. Mean residual alignment: Avoid bins that deviate significantly from the mean,
    // as they tend to create "dead" bins early.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Scarcity heuristic: If only one bin fits, prioritize it heavily to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Tightness reward: Favor bins that become very full (Best Fit principle).
    score -= (bin_capacity - post_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (gaps < 10 are usually hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item fits in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // If this is the only bin that can fit the item, we are forced to take it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Dynamic thresholding for new bin creation
    if is_new_bin {
        // Only open a new bin if the mean residual is already quite low (tight packing)
        // or if we are nearing the end of the sequence
        let new_bin_threshold = 15.0 + (progress * 30.0);
        if mean_residual > new_bin_threshold {
            score -= 10.0; 
        } else {
            score += 60.0; // Heavily penalize new bin if existing bins have space
        }
    }

    // Reward bins that maintain a residual close to the global mean to keep packings uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Base heuristic: Minimize remaining space (Best Fit), but penalize very small residuals
    // that are too small to fit typical future items (e.g., < 10).
    // The "dead space" penalty increases as the stream progresses.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        10.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead influence: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize the bin.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // New bin avoidance: If this is an empty bin (new bin candidate), only pick it if
    // the alternative (fitting_bins_count > 0) is extremely poor.
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one is available
            50.0 + (progress * 50.0)
        } else {
            // If no fit is possible, this is the only choice
            -100.0
        }
    } else {
        0.0
    };

    // Combine factors:
    // We want the lowest score. Best Fit is achieved by low post_residual.
    // We add penalties for bad fit, lookahead mismatch, and unnecessary bin creation.
    let score = post_res_f 
        + dead_space_penalty 
        + lookahead_penalty 
        + new_bin_bias 
        + (open_bins_count as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space that is too small for common items (below 10)
    if post_residual > 0 && post_residual < 10 {
