    score += (post_residual as f64).powf(1.2);

    // 2. Harmonic Class Logic:
    // If the post_residual is small, it might be unusable for future items.
    // If post_residual is < 10, it is likely "dead space" because min item size is typically ~10.
    if post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Integration:
    // If next_item_size can fit into the post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Bin Scarcity:
    // If this is the only bin that can fit the item, we lower the score to force selection.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the current open bins are "bad" (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0; // Moderate penalty to encourage using existing bins
        } else {
            score += 60.0; // Heavy penalty to prevent unnecessary new bin creation
        }
    }

    // 6. Progression scaling:
    // As we near the end of the stream, prioritize tight packing over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post_res = post_residual as f64;
