    // 5. Fitting Constraint: If this is the only bin that can fit the current item, 
    // force its selection to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Mean Balancing: Discourage bins that deviate significantly from the mean 
    // residual of other open bins (keeping bin usage uniform).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
