    // We heavily penalize residuals in the 1-9 range as they are statistically 
    // unlikely to fit subsequent items (min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, prioritize bins that leave
    // larger residuals to accommodate the future item.
    if next_item_size > 0 {
        let next_diff = (post_res - next_item_size as f64).abs();
        if post_res < next_item_size as f64 {
            // Strong penalty for bins that cannot fit the next item
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= 15.0 * (1.0 - (next_diff / 100.0));
        }
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears completion, we become more conservative about opening new bins.
    // fitting_bins_count == 0 implies a new bin.
    if fitting_bins_count == 0 {
        // Penalty for opening a new bin increases as we approach the end of the stream
        // to encourage packing into existing bins.
        score += 25.0 * (1.0 + progress);
    } else {
        // If we have fitting bins, slightly favor those that bring the mean residual 
        // closer to the item_size, keeping bins balanced.
        score -= 5.0 * (1.0 - (post_res / mean_residual).min(1.0));
    }

    // Interaction term: Penalize fragmentation when open_bins_count is high.
    score += (open_bins_count as f64 * 0.5) * (post_res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

