    // 3. Pressure management: If we are running out of bins or late in the stream, 
    // favor bins that keep the mean_residual low (tight packing)
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 2.0;

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the item, 
    // strongly prefer it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. New Bin Penalty: If this is a new bin candidate, add a significant constant 
    // to force the algorithm to prioritize existing bins unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 6. Modulo-based "Harmonic Class" alignment:
    // Prefer binning items such that the post_residual aligns with common item divisors
    let alignment = (post_residual % 25) as f64;
    score += alignment * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
