        // 4. Fragment Avoidance: Penalize residuals that are too small to fit common items (e.g., < 10).
        // This encourages "Best Fit" to leave larger gaps rather than "sliver" gaps.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }

        // 5. Global State Balancing: If the average residual of open bins is high,
        // we are spreading items too thin. Penalize placing into bins that increase this average.
        if (post_residual as f64) > mean_residual {
            score += 5.0 * (open_bins_count as f64 / 20.0).min(1.0);
        }
    }

    // 6. Final constraint: If this is the last chance for an item, prioritize it heavily
    // to avoid leaving items stranded.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps that are too small to fit common items (10-30 range)
    // We use a non-linear penalty for small, unusable residuals
    let waste_penalty = if post < 10.0 && post > 0.0 {
        200.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Reward placing items into bins that bring the residual closer to the global mean
    // This encourages bin leveling
    let leveling_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if we have a large item coming next, prefer keeping bins with 
    // larger residuals open, or avoid creating tiny residuals that block future fits.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 && post > 0.0 {
        150.0 * (1.0 - (post / next_item_size as f64))
    } else {
        0.0
    };

    // Dynamically adjust strategy based on stream progress. 
    // Early on: prioritize tight packing (Best Fit).
    // Late on: prioritize opening new bins to clear out remaining items faster.
    let progress_weight = 1.0 + (progress * 2.0);

    // If bin is empty (new bin candidate)
    let base_score = if bin_residual == bin_capacity {
        // Only open a new bin if the current fitting options are extremely poor
        // or if we are nearing the end of the stream and need to distribute items
        (15.0 * progress_weight) + (mean_residual * 0.5)
    } else {
        post + waste_penalty + leveling_penalty + lookahead_penalty
    };

    // Penalize creating excessive open bins
    let open_bins_penalty = (open_bins_count as f64).powf(1.2) * 2.0;

    base_score + open_bins_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit logic: Minimize post_residual (already in score).
    // 2. Penalize fragmentation: If post_residual is small but > 0, it's often wasted space.
    // We add a penalty for "unusable" small residuals (e.g., < 10), unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: Try to fit the next_item_size into the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Best-Fit-Lookahead).
            score -= 15.0;
        } else {
            // Penalize bins that leave just enough space for nothing useful.
            score += 5.0;
        }
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple of common item sizes (e.g., 20, 25).
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New Bin logic: Only open a new bin if the mean residual is high enough to suggest 
    // current bins are poorly utilized, or if we have no better options.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            // Penalize opening a new bin if existing bins have plenty of room.
            score += 40.0;
        } else {
            // Neutralize new bin opening cost.
            score += 20.0;
        }
    }

    // 6. Progressive scaling: As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Last chance heuristic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

