    // If the post_residual is small but not zero (e.g., 1-9), it often creates 
    // unusable gaps. We penalize this quadratically as the stream progresses.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * (1.0 + progress);
    }

    // Lookahead logic:
    // If we have a next item, check if it fits into the current post_residual.
    // If it fits perfectly, reward this bin heavily.
    if next_item_size > 0 {
