            // is left that could have been used by the next item.
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Heuristic for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), score it based on 
    // the mean_residual of existing bins. If the existing bins are already 
    // very full (low mean_residual), we are less likely to open a new one.
    if bin_residual == bin_capacity {
        score += mean_residual * 2.0;
        // Increase threshold to open new bins as we approach end of stream
        score += (1.0 - progress) * 20.0;
    }

    // Fitting constraint:
    // If this is the only bin that can fit the item, give it a significant 
    // boost to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
