    let variance_penalty = (post - mean_residual).abs() * 0.1;

    // Aggregate score: lower is better.
    // post_residual serves as the primary Best-Fit anchor.
    post + next_fit_bonus + dead_space_penalty + new_bin_penalty + variance_penalty
}

