            let fit_delta = (post_residual - next_item_size) as f64;
            score -= (20.0 / (1.0 + fit_delta));
        }
    }

    // Adaptivity: If we are late in the stream, become more aggressive about 
    // filling existing bins to reduce open_bins_count
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // Penalty for bins that deviate significantly from the mean_residual
    // This promotes balancing the fill levels across open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // If this is the last chance for the current item, lower the cost to prevent
    // creating a new bin unless absolutely necessary
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimizing post_residual), but apply a penalty for 
    // creating "unusable" gaps (residuals < 10) and reward packing based on 
    // lookahead capability (next_item_size).

    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": 
    // If post_residual is small but > 0, it's hard to fill. 
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead optimization:
    // If the next item can fit in the current post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // 3. Global State adjustment:
    // If we have many open bins, prioritize tighter packing.
    // If we have few open bins, be more willing to accept a new bin (if this is a new bin call).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the mean residual of existing bins is already quite low,
        // or if we have very few open bins (avoiding fragmentation).
        score += (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    } else {
        // Penalty for bins that would be the "last chance" for this item if they are a poor fit.
        if fitting_bins_count == 1 && post_residual > 20 {
            score += 15.0;
        }
    }

    // 4. Dynamic pressure:
    // As we approach the end of the stream, prioritize space density heavily.
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": bins with very small residuals are hard to fill later.
    // We penalize residuals between 1 and 9 (the "gap trap").
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item is large, avoid leaving a bin too small for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 * (1.0 - (post_res / next_item_size as f64));
    }

    // Progression logic: As we approach the end of the stream, prioritize closing bins
    // by heavily penalizing opening new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales non-linearly with stream progress
        let new_bin_penalty = 15.0 + (30.0 * progress.powi(2));
        score += new_bin_penalty;
    }

    // Global state awareness: If we have many open bins, penalize leaving large residuals
    // to encourage consolidating items into existing bins.
    if open_bins_count > 5 {
        score += (post_res / bin_capacity as f64) * 10.0;
    }

    // Reward bins that bring the current bin's residual closer to the global mean residual
    // to keep bin fill levels consistent.
    let residual_diff = (post_res - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (small remainders that are hard to fill).
    // Specifically, residuals between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if we know the next item, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain potential for the next item.
            score -= 25.0;
        } else {
            // Penalize if this placement prevents the next item from fitting in this bin.
            score += 15.0;
        }
    }

    // Harmonic/Modulo logic: prioritize filling bins to specific "round" thresholds.
    // 100/2=50, 100/3=33, 100/4=25.
    let mod_val = post_residual % 25;
    if mod_val == 0 {
        score -= 10.0;
    }

    // If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only choose it if the current density is low or we have no good fits.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            // New bins are expensive; penalize unless the average bin is very empty.
            score += 60.0;
        } else {
            score += 45.0;
        }
    }

    // Progression scaling: be more conservative as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit the smallest
    // possible items (assuming 10 as effective lower bound), it is "wasted" space.
    if post_residual > 0 && post_residual < 10 {
