    // If we are late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 40.0) + (open_bins_count as f64 * 2.0);
    }

    // 4. Compactness Bias: If this is the only bin that fits, we are forced,
