    // If post_residual is small but not zero, it's often a "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Global distribution awareness: 
    // If the current bin is tighter than the mean, it's a good candidate for smaller items.
    // We reward keeping the mean residual balanced.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression scaling: 
    // As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

