            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no other bin fits, this is a forced new bin
            score = 0.0;
        }
    } else {
        // Reward: Best Fit Decreasing logic (favor tighter residual)
        // Penalty: Avoid "fragmentation" (small residuals that can't fit future items)
        if post_residual > 0 && post_residual < 10 {
