            }
        }

        // Dynamic adjustment based on progression
        // As we approach the end, prioritize filling existing bins over "perfect" fits
        score -= progress * 10.0 * (open_bins_count as f64 / 10.0);
    }

    // Penalty for creating a bin with a very high residual compared to the global average
    if post_residual > (mean_residual as u32 + 20) {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
