    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalty proportional to how much we "missed" the next item by.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. Reward bins that remain close to the global mean residual to keep distribution uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. If this is the last chance to fit an item (fitting_bins_count == 1), 
    // aggressively prioritize this bin to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progressive thresholding: as we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
