    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Global State Penalty: If we have many open bins, penalize opening a new one.
    // The new bin case is identified by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
        // Only open a new bin if we have no good options (high fitting_bins_count penalty)
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Best-Fit refinement: Favor bins that are already closer to being filled (low mean_residual).
    // This keeps the "tightest" bins tighter.
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening new bins: scale by progress to discourage early fragmentation
    // but allow it if the current fit is extremely poor (large post_residual).
    if is_new_bin {
        score += 15.0 + (progress * 30.0);
    }

    // Heuristic: Prefer bins that leave space for the next item if known.
    // If next_item_size is known, penalize bins that leave a gap too small for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Interaction term: Penalize creating bins with residuals significantly lower than the mean.
    // This promotes filling bins somewhat uniformly to avoid leaving many tiny, unusable gaps.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // Special constraint: If this is the only bin that fits, prioritize it heavily
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Non-linear coupling: Exponential penalty for very small residuals (potential dead space)
    // that are too small to fit any common item (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_residual as f64).powf(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
