    // This forces tighter packing early on and allows opening new bins only when necessary later.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (20.0 + (progress * 60.0));

    // Best-Fit Decreasing logic: favor small post_residuals (tight fits).
    // Non-linear coupling: squaring the post_residual penalizes large gaps exponentially.
    let fit_score = (post * post) / 10.0;

