    if is_new_bin {
        // Only open a new bin if we have many open bins already or if existing bins are poor fits.
        score += (open_bins_count as f64 * 2.0) + 15.0;
    } else {
        // Reward filling existing bins to keep open_bins_count low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting Constraint: If this is the only bin that fits, heavily favor it to avoid new bin overhead.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Global state balancing: Avoid creating bins with significantly lower residuals than the mean.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
