    // 4. Global State Balancing: If the mean residual is high, we are under-utilizing 
    // capacity; penalize creating new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        if open_bins_count > 0 {
            score += 25.0;
        }
    }

    // 5. Harmonic Modulo Coupling: Prefer bins that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25) to increase chances of future fit.
    if post_residual > 0 {
        let remainder = post_residual % 20;
        if remainder == 0 {
            score -= 10.0;
        }
    }

    // 6. Progress Scaling: As the stream nears completion, tighten constraints to force
    // tighter packing and reduce the impact of trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any common item 
    // (assuming 10 is the practical lower bound), heavily penalize the gap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly in the 
    // remaining space, reward this bin choice.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 0.5;
    }

    // 3. Open Bin Pressure: If this is an existing bin (not a new one), penalize 
    // opening new bins by lowering the score of existing bins proportional to how
    // many bins are already open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Penalize opening a new bin if there are other bins that could have taken it
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 5.0);
        }
    }

    // 4. Global Density Awareness: If the mean residual of current bins is high, 
    // prioritize filling existing bins to consolidate space rather than opening new ones.
    if mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (leaving too much empty space).
    // This naturally favors tighter fits.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward this bin.
    // This is the core of the 2-step lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Reward precise pairing (minimizing waste after both items).
        score += (post_residual - next_item_size) as f64 * 0.2;
    }

    // 3. New Bin Thresholding:
    // If this is an empty bin, add a penalty proportional to the open bins count
    // to discourage premature bin opening when space exists elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Global Density Calibration:
    // If the current bin is tighter than the mean, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 5. Urgency Constraint:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residual)
    // to avoid leaving sparse bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
