        // Favor bins that have a residual close to the mean_residual of all bins.
        // This keeps the "tightness" of bins consistent.
        let deviation = (post as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the last fitting bin, slightly reward using it to avoid opening a new one.
        if fitting_bins_count == 1 {
