    // Harmonic preference: Favor bins that leave residuals which are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps align bin space with standard item packing patterns.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    // Lookahead logic: If a next item exists, penalize bins that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
