    }

    // Special case: If this is the last chance for the current item, reduce penalty for poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, 
    // but penalize post_residual values that are too small to be useful (dead space),
    // while scaling by open_bins_count to discourage fragmentation.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is positive but smaller than the smallest 
    // likely item (10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
