            score += 5.0;
        }
    }

    // 4. Fitting bin consolidation: If only one bin can fit the item, 
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Normalization against mean_residual: Favor bins that stay close to the average
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
