pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) which are hard to fill given the input distribution
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Favor bins that leave space matching the likely size of the next item (lookahead)
