    let temporal_pressure = (1.0 - progress) * (mean_residual - post);

    // If this is a new bin, apply a heavy penalty that decreases as the stream nears the end
    // (Opening a new bin is expensive, but necessary if all open bins are poor fits)
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 + (progress * 20.0)
    } else {
        0.0
    };

    // Combine terms:
    // Low score = high priority. 
    // We want small post_residual, low fragmentation, and alignment with next_item_size.
    post + fragmentation_penalty + lookahead_alignment + temporal_pressure + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
