    // 2. Penalty for creating "dead space" (small residuals that cannot fit common items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: if next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global state: If we are near the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 5. New Bin logic: Only open a new bin if the current residual is very poor for existing bins
    // or if we have very few open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits the item
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary to open a new bin
            score -= 10.0;
        }
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly from the mean
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating a 'dead zone' (residual space too small for most items)
    // We penalize post_residual values that are likely to be wasted (e.g., < 10)
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If this bin fits the item, check if it also fits the next item
    // Reward bins that can accommodate the next item (Best Fit with lookahead)
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 20.0 * (1.0 - progress);
    }

    // Adaptivity: As the stream progresses, become more aggressive about filling gaps
    // to avoid leaving too many fragmented bins open.
    if fitting_bins_count == 1 {
        // Last chance to fit in an existing bin, reduce score to favor this over a new bin
        score -= 5.0;
    }

    // Penalty for opening new bins: 
    // Only open a new bin if the residual fragmentation is too high across all bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress and the number of already open bins
        // This forces the algorithm to consolidate items into existing bins early on.
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // Interaction term: penalize deviation from the mean residual to maintain uniform bin usage
    let residual_diff = (post - mean_residual).abs();
    score += 0.5 * residual_diff * progress;

