pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #601: Harmonic Residual Optimization
    // Targets Best-Fit-Decreasing approximation by penalizing small remaining gaps (fragmentation)
    // and favoring bins that can accommodate the next item (lookahead).

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: Penalize gaps that are too small to fit any likely future items (e.g., < 20).
    // If post_residual is in [1, 19], it's "dead space". We heavily penalize this.
    if post_residual > 0 && post_residual < 20 {
