    // We reward post_residual values that are close to 0 or specific multiples of 10.
    let harmonic_penalty = (post_residual % 10) as f64;
    score += harmonic_penalty * 0.5;

    // 4. Global Density Control: If we have many open bins, prioritize closing them (lower residual).
    // If we have few, be more conservative about opening new ones.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // Only open a new bin if the average residual is already high (wasting space).
        score += (open_bins_count as f64) * 2.0;
        score += mean_residual * 0.5;
    } else {
        // If this is the last bin that can fit the item, give it a massive priority boost.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
