    } else {
        0.0
    };

    // Calculate "tightness" of the fit.
    // Smaller post_residual is generally better (Best Fit).
    // We use an exponential weight to prioritize near-zero residuals.
    let fit_score = (post * post) / (bin_capacity as f64);

