    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals that create "dead space" (e.g., 1-9).
    // Small residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Integration: If the next item fits into the post_residual, 
    // significantly lower the score to encourage perfect pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // 4. Global State Awareness: If opening a new bin is being considered (bin_residual == bin_capacity),
    // heavily penalize it unless the mean_residual of existing bins is already very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average space wasted in existing bins is large.
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score = 0.0; // Must open the first bin.
        }
    } else {
        // Reward bins that have residuals closer to the global mean to keep packing uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // If post_residual is small but > 0, it is likely to become unusable space.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * 2.0
    } else {
        0.0
    };

    // Reward bins that can accommodate the next item (lookahead).
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Favor filling bins closer to capacity as the stream progresses.
    // We heavily penalize opening a new bin (where bin_residual == bin_capacity)
    // unless the fit in existing bins is extremely poor.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Interaction between mean_residual and current post_residual to balance
    // the load across existing bins.
    let balance_factor = (post - mean_residual).powi(2) * 0.1;

    // Final score: prioritize tightest fit (post) while accounting for
    // fragmentation, lookahead, and the cost of opening new bins.
    let score = post + fragmentation_penalty + lookahead_reward + new_bin_penalty + balance_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to keep bins tight.
    // Penalty is exponential to force packing into the smallest available space.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic:
    // If the post_residual is a small fraction of the capacity, it's "wasted" space for large items.
    // We reward placements that leave space divisible by common item sizes (e.g., 20, 25).
    if post_residual > 0 {
        let modular_waste = (post_residual % 20) as f64;
        score += modular_waste * 2.5;
    }

    // 3. Lookahead Logic (Next Item Coupling):
    // If next_item_size is large, avoid leaving a residual that is slightly too small for it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // 4. Structural conservation:
    // Avoid opening new bins unless the current options are very poor (high residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;
        // If there are bins that can fit the item, discourage opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    if mean_residual > 0.0 {
        score -= (mean_residual * 0.2);
    }

    // 6. Final adjustment for "tightness":
    // If we have a perfect fit, reward it significantly.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

