}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "slivers" (very small residuals that are hard to fill later)
    // We penalize residuals between 1 and 15 specifically.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res) * 2.5;
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    // We subtract from the score to lower it (increase priority) if the post_residual
    // is sufficient to hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
