    // Dynamic scaling based on stream progression.
    // Late in the stream, we become more conservative about opening new bins
    // to avoid leaving too many bins with large residuals.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // Penalize opening a new bin increasingly as we approach the end of the stream.
        score += 20.0 + (progress * 40.0);
    } else {
        // Reward filling existing bins, weighted by how many other bins could fit this item.
        // If fitting_bins_count is low, this bin is more precious.
        score -= (1.0 / (fitting_bins_count as f64 + 1.0)) * 10.0;
    }

    // Non-linear coupling: penalize high mean_residual relative to current bin state
    // to encourage compaction.
    score += (mean_residual - post_res).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
