    }

    // 3. Mean Residual Balancing: Penalize bins that deviate significantly from the mean residual.
    // This encourages uniformity in bin usage, preventing "stranded" high-capacity bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. New Bin Thresholding: Discourage opening new bins unless the current fit is extremely poor.
    // If we are evaluating the empty bin (bin_residual == capacity):
    if bin_residual == bin_capacity {
        // Only open a new bin if the average post_residual would be terrible otherwise.
        // We set a threshold based on the mean_residual of current bins.
        if mean_residual < 15.0 {
