    // (1-9) but too large to be considered "tight" packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global pressure: Penalize opening new bins when current open_bins_count is high.
    // If this is a new bin candidate, increase its score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Tightness bias: If this bin is the last chance for the item (fitting_bins_count == 1),
    // reduce the penalty for a poor post_residual to ensure we don't force a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. Normalization: Discourage bins that are significantly below the mean residual
    // to keep the spread of space usage balanced.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
