pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // but weigh it against the item size to avoid creating unfillable gaps.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // heavily reward this bin to keep it "active" for the next step.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
    }

    // 3. Dynamic Thresholding for New Bins:
    // If the bin is brand new (bin_residual == bin_capacity), penalize it based on 
