        // Base cost to open a new bin is high; decreases slightly as we reach the end of the stream.
        let spawn_penalty = 150.0 * (1.0 - progress * 0.2);
        score += spawn_penalty;

        // If other bins could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 200.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // 4. Global state balancing: 
        // Penalize bins that deviate too far from the mean_residual to keep bin filling uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Final adjustment: Prefer filling bins that are already nearly full (Best-Fit variant).
    // This reduces the number of bins with small, unusable residuals.
    if post_residual < 10 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a new bin:
    // If this is the "new bin" candidate (bin_residual == bin_capacity), 
    // we penalize it significantly early in the stream to force reuse,
    // but allow it more freedom as the stream progresses.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.5 - progress);
    }

    // Lookahead logic:
    // If the next item exists, penalize bins that would leave a residual 
    // smaller than the next item (creating "dead space" that cannot be filled).
    if next_item_size > 0 {
        if post < (next_item_size as f64) {
            score += (next_item_size as f64 - post) * 1.2;
        }
    }

    // Dynamic Pressure:
    // If there are very few bins that can fit the current item, 
    // we prioritize preserving the most "flexible" bins (those with higher residuals).
    // Conversely, if many bins fit, we favor the tightest fit.
    if fitting_bins_count > 0 {
        let fit_ratio = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);
        score += (post * fit_ratio).powf(1.1);
    }

    // Global balance:
    // Penalize bins that are significantly further from the mean residual 
    // to keep the bin distribution uniform.
    let dev = (post - mean_residual).abs();
    score += dev * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (post_residual < 10)
    // Small residuals are usually worse than empty space if they prevent future fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic lookahead: If the next item fits perfectly into this post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 0.5;
    }

    // 3. Bin-Opening Logic: Only open a new bin if the existing options are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin heavily unless the mean residual is already quite low,
        // suggesting we are running out of space in current bins.
        score += 40.0 + (mean_residual * 0.5);
    } else {
        // Encourage filling bins that are already "half-full" or more to keep the mean_residual stable.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;
    }

    // 4. Harmonic capacity distribution:
    // Prefer placing in bins where the resulting residual is a multiple of larger factors
    // to keep space flexible for future items (which are often 20-50 range).
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Progression adjustment: Towards the end of the stream, prioritize tight packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
