    }

    // 3. Pressure management: If this is the only bin that fits the item, make it highly attractive
    // to avoid opening a new bin (which is usually expensive).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 4. Distribution balancing: If current bin residual is far from the mean,
    // push toward normalization to keep bins somewhat uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 5. Threshold logic: If we are opening a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty unless the average residual is already very low,
    // indicating we are running out of space in existing bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
