    // Interaction 2: Favor bins that align with the lookahead (next_item_size).
    // If the post_residual can fit the next item, we reward this bin heavily.
    if next_item_size > 0 && post_res >= next_item_size as f64 {
        score -= (next_item_size as f64 / cap) * 50.0 * (1.0 - progress);
