        // Opening a new bin is penalized based on progress and current open bin volume
        score += 40.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    }

    // Penalty for creating "slivers" (very small, unusable spaces)
    // Spaces between 1 and 9 are notoriously difficult to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Heavy penalty for wasted space that is larger than the next item but still small
    // Encourages keeping space for future potential fits
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < (next_item_size + 5) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the returned score.
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items).
    // If post_residual is < 10, it's likely to be unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that keep capacity for the next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // Penalize "blocking" the next item
        }
    }

    // 3. Global state: If fitting_bins_count is low, we are constrained.
    // If this is the only bin that fits (fitting_bins_count == 1), prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual > 20 {
        score -= 10.0;
    }

    // 4. Dynamic threshold: Discourage opening a new bin unless existing bins are very full.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very low.
        if mean_residual > 15.0 && open_bins_count > 0 {
            score += 40.0; // Strong penalty against opening new bins early
        } else {
            score += 20.0; // Moderate penalty
        }
    }

    // 5. Time horizon: As we reach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Tighten restrictions at the end of the stream
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    let mut score = post * post;

    // Penalty for leaving "dead space" that is too small for common items.
    // If the post_residual is smaller than the smallest possible item (1), it's perfect (0).
    // If it's between 1 and 9, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 2500.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item is large, avoid bins that leave just enough 
    // space to be useless for the next item but too small for the current bin's efficiency.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 1200.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // in packing tightly to minimize the final bin count.
    let density_factor = (open_bins_count as f64) / (step_index as f64 + 1.0).sqrt();
    score += density_factor * 500.0 * progress;

    // New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate an "opening cost".
    // We only want to open a new bin if the existing fits are objectively terrible.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, modulated by the number of bins already open.
        // As we reach the end of the stream, the cost to open a new bin decreases slightly 
        // to ensure we don't force a bad fit at the very end.
        score = 8000.0 + (open_bins_count as f64 * 100.0) - (progress * 2000.0);
    } else {
        // If it's not a new bin, apply a slight reward for filling bins that are 
        // currently below the mean residual to keep bin usage balanced.
        if (bin_residual as f64) > mean_residual {
            score -= 200.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Lookahead: If next_item_size fits in post_residual, reward this bin
    // This effectively implements a Best-Fit-Decreasing-like lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 * 2.5);
    }

    // 3. Fragmentation Penalty: Penalize post_residuals that are too small to hold common items 
    // but large enough to waste space (the "useless remainder" problem).
    // Items < 20 are common; if we leave < 10, it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin. 
        // Only open if fitting_bins_count is 0, or if existing bins are all "bad" fits.
        score += 45.0;

        // If we are near the end of the stream, increase cost of new bins to favor compaction.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean residual equilibrium: Favor bins that stay near the global mean residual
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Last chance logic: If this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

