    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Fragmentation control: penalize creating small unusable slivers (< 10)
    // Unless it's a perfect fit (0)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 6. Progressive tightening: as the stream nears the end, become more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
