pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual (tighter fit) is generally better (Best-Fit approach).
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it often prevents larger items from fitting. We penalize small non-zero gaps 
    // exponentially to prefer perfectly filled bins.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powf(1.5);
    }

    // Lookahead logic: if the next item is large, we want to preserve bins with 
    // larger residuals. If next_item_size is large, increase score of bins 
    // that would result in a small post_residual (making them less attractive).
    if next_item_size > 0 {
        let next_item_factor = (next_item_size as f64) / (bin_capacity as f64);
        score += next_item_factor * (bin_capacity as f64 - post);
    }

    // Dynamic thresholding based on stream progress: 
    // Near the end of the stream, we become more aggressive in forcing tight fits
    // by penalizing empty space more heavily.
    score += (1.0 - progress) * (bin_capacity as f64 - mean_residual);

    // If this is a new bin (bin_residual == bin_capacity):
    // Only choose a new bin if the current `fitting_bins_count` is zero,
    // or if the average residual of existing bins is already very low, 
    // suggesting current bins are too fragmented to be useful.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one could work,
            // unless the existing bins are extremely crowded.
            score += 100.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
    }

    // Interaction term: favor bins that keep the mean_residual high early in the stream,
    // but favor low mean_residual late in the stream to consolidate packing.
    score += (open_bins_count as f64) * (0.5 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
