pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep space tight.
    // 2. Lookahead: If post_residual is close to next_item_size, reward the placement.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements where the remaining space perfectly accommodates the next item.
        score -= 50.0 * (1.0 / (1.0 + diff));
    }

    // 3. New Bin Penalty: If this is an empty bin, add a significant penalty to avoid 
    // opening new bins unless the fit is absolutely necessary.
    if bin_residual == bin_capacity {
        score += 45.0; 

        // If we are at the end of the stream, relax the penalty to avoid stranded items.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // 4. Residual Balancing: If this placement makes the bin's residual significantly 
    // lower than the global mean, it might be a good way to "clean up" space.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimizing post_residual) but apply penalties for 
    // creating "fragmented" space that can't accommodate the next item or common item sizes.

    let mut score = post_residual as f64;

    // Penalty for creating a "gap" that is too small for common items (e.g., < 10)
    // but not empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item doesn't fit in the remaining space, 
    // we penalize this placement slightly to encourage keeping the bin open 
    // for a better fit, unless the current bin is already quite full.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to minimize new bin openings.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // Global state awareness: If we have many open bins, heavily penalize opening a new one.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If this bin is a "tight fit" (post_residual is small), reward it.
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // Penalize if this is the only bin that fits, to prevent "stranding" 
    // the item if better options were available (though Best-Fit handles most).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses to consolidate space
    let mut score = post_residual as f64;

    if is_new_bin {
        // Base cost for opening a new bin is the capacity, scaled by progress to force usage of existing bins
        score = bin_capacity as f64 * (1.5 - (0.5 * progress));

        // If we have many fitting bins, opening a new one is highly suboptimal
        score += (fitting_bins_count as f64) * 20.0;
    } else {
        // Best Fit Decreasing logic: minimize post_residual (the base score)
        // Add penalty for creating "fragmented" space (small, unusable residuals)
        // A residual < 10 is often dead space for items sized 10-80
        if post_residual < 10 && post_residual > 0 {
            score += 15.0 * (1.0 - progress);
        }

        // Lookahead heuristic: if next item exists, favor bins that can accommodate it
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0 * (1.0 - progress);
            } else {
                score += 5.0 * progress;
            }
        }

        // Penalize deviations from the current mean residual to keep bins packed evenly
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: Reward bins that fit the NEXT item perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= (next_item_size as f64) * 0.8;
            // Heavily reward "perfect" fits for the next item
            if post_residual == next_item_size {
                score -= 25.0;
            }
        }
    }

    // 3. Penalty for opening new bins prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many items left and current bins are "polluted"
        // with small residuals that make them inefficient for future items.
        score += 35.0; 
        if fitting_bins_count > 0 {
            score += 20.0; // Discourage opening new bin if existing ones work
        }
    }

    // 4. Harmonic/Modulo optimization:
    // Penalize residuals that fall into the "dead zone" (too small to fit most items)
    // Most items are >= 10, so residuals < 10 are often wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // 5. Global efficiency:
    // If we are nearing the end of the stream, prioritize packing tighter
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Balance the number of open bins
    // If we have too many bins open, penalize the creation of new ones
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to become unusable.
    // We penalize this heavily to force the packing of larger items or creation of cleaner bins.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If we are evaluating the "new bin" candidate (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // Reward utilizing existing bins to reduce fragmentation.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the mean 
    // residual of the current set to promote uniform packing density.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely item (less than 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Reward bins that maintain enough space for the next item without being too wasteful.
            score -= 10.0;
        }
    }

    // 3. Balance utilization: Penalize bins that deviate significantly from the mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. Strategic New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty to discourage 
    // opening new bins unless the fit in existing bins is truly abysmal (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the best existing fit is extremely wasteful (e.g., > 40 remaining).
            score += 40.0;
        } else {
            // No bins fit, forced to open.
            score -= 50.0;
        }
    }

    // 5. Progression weighting: As we approach the end of the stream, prioritize tightest fit (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize large gaps remaining after placement.
    // We favor smaller post_residuals (Best Fit logic).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Coupling: If next item is large, avoid leaving a tight gap.
    // If the post_residual is smaller than the next item, we create a "dead" bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Global State Balancing: Use mean_residual to avoid fragmenting bins.
    // If this bin is significantly emptier than the average, prioritize filling it.
    if bin_residual > (mean_residual as u32) {
        score -= (bin_residual - mean_residual as u32) as f64 * 0.8;
    }

    // 4. Scarcity/Urgency: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Dynamic Threshold for New Bins:
    // As the stream progresses, increase the cost of opening new bins.
    if is_new_bin {
        score += 35.0 + (progress * 20.0);
        // If we still have many bins open, penalize opening more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Tightness Bonus: Reward perfect fits (zero post_residual).
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragment" (small residual space that is hard to fill).
    // If post_residual is small but > 0, it is often worse than 0.
    // We penalize values < 10 exponentially.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it 
    // after the current placement.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream nears the end, prioritize closing bins 
    // (lower open_bins_count) over perfect packing.
    score += (open_bins_count as f64) * progress * 2.0;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // based on how many existing bins could have fit the item.
    // Only open a new bin if the current fit is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a barrier to prevent opening a new bin if others exist.
            score += 80.0 + (mean_residual * 0.5);
        } else {
            // No other bins fit, so this is a mandatory new bin.
            score = 0.0;
        }
    }

    // Adjust for mean residual: avoid bins that are significantly "emptier" 
    // than the current average to maintain tight packing.
    score += (post - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize keeping residuals large enough for at least one more item (e.g., > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item lookahead optimization:
    // If the next item fits in the current post_residual, we favor this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Harmonic class logic:
    // Penalize bins that leave a residual that is a poor multiple of common item sizes.
    // Modulo 20 represents a balance between standard item distribution granularities.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // Scarcity/Efficiency weighting:
    // If we have few fitting bins, we are forced to be more conservative.
    // If fitting_bins_count is 1, this is a "last chance" bin; we should be slightly less
    // picky about the residual to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Empty bin management:
    // If bin_residual == bin_capacity, we are evaluating opening a brand new bin.
    // We only want to do this if our current open bins are all "cluttered" (small residuals).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            // If existing bins have plenty of space, opening a new one is inefficient.
            score += 50.0;
        } else {
            // Otherwise, opening a new bin is neutral.
            score += 10.0;
        }
    }

    // Progress-based scaling:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

