pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    // We use a non-linear penalty on the post_residual to favor bins that leave less space
    let mut score = post_res.powf(1.5);

    // Lookahead Penalty: If the next item is large, penalize small post_residuals 
    // that would strand the bin and force a new bin for the next item.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64) / (post_res + 1.0);
        score += lookahead_pressure * 10.0;
    }

    // Dynamic Thresholding: As the stream nears completion, become more aggressive 
    // about packing into existing bins to avoid opening new ones.
    let exhaustion_factor = (1.0 - progress).powi(2);
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * exhaustion_factor;
    }

    // Penalty for opening new bins: if bin_residual is capacity, this is a new bin.
    // We add a scaling cost based on how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // Coupling with mean_residual: avoid bins that deviate significantly from 
    // the average state of the system to maintain uniform packing density.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are too small to fit common items
    // (10-80 range means < 10 is almost always unusable waste).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit logic: prioritize bins where the post_residual is minimized.
    // We favor smaller post_residuals to pack bins tightly.

    // Lookahead logic: if the next item fits into the current post_residual, 
    // we heavily prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic/Modulo logic: prioritize bins that leave "clean" residuals
    // that are multiples of 25 (common factors in 100), as they are more versatile.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 15.0;
    }

    // Threshold management: if this is the last fitting bin, avoid opening a new bin
    // unless the current fit is extremely poor (post_residual > 40).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 40 {
            score += 60.0;
        } else {
            score -= 30.0;
        }
    }

    // If considering a new bin (bin_residual == bin_capacity), penalize it 
    // unless the open bins are mostly full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // Progression scaling: as we near the end of the stream, prioritize 
    // closing bins (lower post_residual) over saving space for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

