        if bin_residual == bin_capacity {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Residual Balancing: Compare the bin's state to the mean_residual.
    // We prefer bins that are already "below average" in terms of free space to keep the
    // remaining bins more "open" for larger items.
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff * 0.5;

    // 5. Stream Progression: As we approach the end of the stream, prioritize 
    // closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower values mean better bin.

    // 1. Base Score: The post_residual is the primary metric.
    // Smaller post_residual is generally better (Best Fit).
    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable space (Dead Space):
    // If post_residual is small but > 0, it's often better than being 0 if it traps space.
    // However, if post_residual is < 10 (the minimum item size), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic:
    // If we have a next item, check if it fits in the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Lookahead optimization)
            score -= 15.0;
        } else {
            // Penalize bins that leave just enough space to be unusable for next_item_size
            score += 5.0;
        }
    }

    // 4. Global State Consideration:
    // If this is the only bin that can fit the current item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Handling New Bin Candidate:
    // When bin_residual == bin_capacity, we are evaluating a brand new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full),
        // making it harder to fit new items efficiently.
        if mean_residual < 15.0 {
            score += 5.0;
        } else {
            score += 35.0; // Strong penalty for opening new bins if existing ones have space.
        }
    }

    // 6. Progress Scaling:
    // Towards the end of the stream, prioritize packing tightly to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we penalize 
    // creating "slivers" of space that are too small to fit likely future items.
    // We use a non-linear penalty for small residuals that are not zero.
    let sliver_penalty = if post_res > 0.0 && post_res < 10.0 {
        25.0 / (post_res + 0.1)
    } else {
        0.0
    };

    // Lookahead logic: if the next item fits into the current post_residual, 
    // we strongly favor this bin.
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -40.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Normalize open bins impact: as the stream progresses, we want to consolidate 
    // rather than spread items across too many bins.
    let consolidation_pressure = (open_bins_count as f64) * progress * 5.0;

    // If this is a new bin (bin_residual == bin_capacity), we penalize it 
    // heavily unless we are forced to open one (fitting_bins_count == 0).
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            -10.0 // Necessary evil
        } else {
            // Discourage opening a new bin if an existing one can fit the item
            50.0 + (progress * 50.0) 
        }
    } else {
        0.0
    };

    // Combine terms: 
    // Base is post_residual (Best Fit). 
    // We want to minimize this score, so we subtract bonuses and add penalties.
    post_res + sliver_penalty + lookahead_bonus + consolidation_pressure + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We prioritize bins that leave the least space (the base score).

    // 2. Lookahead Synergy (Harmonic coupling):
    // If next_item_size can fit into the post_residual, we reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter alignment for the next item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Fragmentation Avoidance:
    // Penalize post_residuals that are too small to fit any common item (e.g., < 10),
    // unless it is an exact fit (zero residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic Thresholding:
    // Favor bins that maintain a residual close to the mean_residual of other bins
    // to keep the capacity distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. New Bin Control:
    // If this is a new bin candidate (bin_residual == bin_capacity),
    // only choose it if the current open bins are all very poorly suited.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins already or if fitting is extremely inefficient
        if open_bins_count > 0 {
            score += 35.0; 
            // Scale penalty by progress: later in the stream, be more conservative
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    } else {
        // If this is the last chance for the current item, prioritize it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
