    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    //    If post_residual < next_item_size, we penalize this bin as it forces a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 50.0 * (1.0 - progress);
        }
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin early in the stream,
    //    but reduce the penalty as we approach the end of the stream (to clear out bins).
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 45.0 * (1.0 - progress);
        } else {
            // Must open a new bin, reduce score to make it the default choice
            score -= 100.0;
        }
    }

    // 4. Global State: If mean_residual is high, we are being too loose. 
    //    Tighten the fit requirement by penalizing bins that leave more than average space.
    if !is_new_bin && (post_residual as f64 > mean_residual) {
        score += 15.0 * progress;
    }

    // 5. Criticality: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit)
    // We apply a non-linear penalty to small residuals that might become "dead space"
    // based on the likelihood of future items fitting in that gap.
    let mut score = post;

    // Penalty for creating a bin with very little space left if the stream is early,
    // as these are high-value slots for future, larger items.
    if post < 20.0 && post > 0.0 {
        score += (20.0 - post) * (1.0 + progress);
    }

    // If this is the only bin that can fit the item, prioritize it heavily 
    // to avoid opening a new bin unnecessarily (Best Fit constraint).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead logic: If the next item is large, penalize residuals that are 
    // too small to accommodate the next item (e.g., < next_item_size).
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one
    // by increasing the score for the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // Favor bins that align with the current mean residual to keep bin states uniform
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero 
    // (the "fragmentation trap") by applying a non-linear cost to residuals < 20.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can still accommodate it.
    // If next_item_size exists and current post_residual is too small for it, we penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
