            score += 55.0 + (open_bins_count as f64 * 0.5);
        }
    } else {
        // 4. Harmonic Density: Favor bins that are already well-packed (low mean_residual).
        // This encourages "Best Fit" behavior by clustering items into filled bins.
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
