    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best-Fit).
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 30.0 + (fitting_bins_count as f64 * 15.0);
    } else {
        // Encourage using existing bins that have a residual close to the current mean.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Progress Scaling: As the stream nears completion, become more conservative 
    // about opening new bins to prevent stranding items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

