            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin, neutralize the penalty
            score = 50.0;
        }
    }

    // 4. Balance the packing density: discourage creating fragments smaller than 10 
    // unless it perfectly fills the bin (post_residual == 0)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global state normalization: discourage fragmentation as the stream ends
    let progress = step_index as f64 / total_items as f64;
    score += (progress * mean_residual) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimal post_residual) but penalize creating "dead zones"
    // that cannot fit potential future items, especially when near the end of the stream.

    let mut score = post_residual as f64;

    // 1. Base Strategy: Minimize post-residual (Standard Best-Fit)
    // Favor bins that leave the least space.

    // 2. Penalty for creating "unusable" small gaps (1..9 range)
    // Gaps smaller than the minimum item size (10) are effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Logic: 
    // If the next item fits into the current post_residual, reduce the score (reward).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Global State Awareness:
    // If we have many open bins, penalize opening a new one unless the fit is perfect.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 45.0 + (mean_residual * 0.5);
        }
        // If it's the very last item, opening a new bin is neutral
        if step_index == total_items - 1 {
            score -= 10.0;
        }
    }

    // 5. Fitting Constraint:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Dynamic Time Horizon:
    // As the stream progresses, prioritize closing bins (lower mean_residual) to keep density high.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "fragmented" space (small, unusable residuals)
    // We penalize residuals that are too small to fit common items (e.g., < 15)
    // but only if we are not near the end of the stream.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 - progress).powf(0.5) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor keeping larger residuals open.
    // If next_item_size is 0 (end of stream), prioritize closing bins (lower score).
    if next_item_size > 0 {
        let next_item_f = next_item_size as f64;
        if post < next_item_f {
            // High penalty if this placement prevents the next item from fitting here
            score += (next_item_f - post) * 2.5;
        }
    } else {
        // End of stream: aggressively reduce residual space.
        score -= post * 0.5;
    }

    // Interaction with mean_residual: 
    // If this bin is significantly emptier than the average, penalize to promote consolidation.
    if bin_residual as f64 > mean_residual * 1.2 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Fitting Bins logic:
    // If this is the only bin that can fit the item, give it a significant boost
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New Bin Candidate Logic:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only want to open a new bin if the current progress is low
    // or if the item is too large for existing bins (handled by high scores elsewhere).
    if bin_residual == bin_capacity {
        // Bias against opening new bins late in the game
        score += 40.0 * progress;
        // Bias against opening new bins if we have many open bins already
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

