    // If we have many items left, prioritize filling the tightest bins first.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 4. New bin avoidance: If fitting_bins_count is 1, this is the only bin that can take the item.
    // We heavily discount this to prevent opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global state normalization: Penalize bins that deviate significantly from the mean residual
