pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (dead space)
    // The "Best Fit" logic is embedded by rewarding smaller post_residuals.
    // We add a non-linear penalty for small residuals that are too small to fit typical future items.
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        15.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, avoid bins that result in small post_residuals.
    // If next_item_size is 0 (end of stream), prioritize filling up existing bins regardless of fit.
    let lookahead_pressure = if next_item_size > 0 {
        let fits_next = if post_res >= next_item_size as f64 { 0.0 } else { 25.0 };
        fits_next * (1.0 - progress)
    } else {
        -50.0 // Aggressively finish bins at end of stream
    };

    // Balance between filling existing bins and keeping them balanced.
    // We penalize opening a new bin (bin_residual == bin_capacity) 
    // unless the fit in existing bins is objectively poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
