    };

    // Coupling: If fitting_bins_count is low, we are running out of options,
    // so we should be less picky about the residual quality.
    let scarcity_factor = (fitting_bins_count as f64).recip().sqrt();

    let score = post_res 
        + dead_space_penalty 
        + lookahead_pressure 
        + (new_bin_penalty * scarcity_factor);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
