    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 4. Tight Fit Reward: If the item fills the bin perfectly, strongly reward it.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global Efficiency: If this bin is the last chance for this item, reduce the penalty 
    // to prevent unnecessary bin creation if the fit is acceptable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items).
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Aggressive 2-step lookahead matching:
    // If the next item fits perfectly into this post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff < 5.0 {
            score -= 40.0; // Strong reward for perfect or near-perfect fit
        }
    }

    // 3. Balancing: Avoid opening a new bin unless necessary.
    // If this is a new bin candidate, heavily penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Global state awareness:
    // If the bin is very empty compared to the mean, prefer filling it to keep the number of bins low.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Last chance bias:
    // If this is the only bin that can fit the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize minimizing open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the waste if we choose this bin.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10, as items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. If this is a new bin (bin_residual == bin_capacity), penalize it 
    // heavily unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0;
        } else {
            // If no other bin fits, this is forced; reduce penalty.
            score -= 10.0;
        }
    }

    // 3. Lookahead logic: If the next item fits into this bin's post_residual,
    // reward this bin to keep the packing dense.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Global state coupling: If we have many open bins, prioritize filling 
    // the ones with the smallest residuals (Best Fit behavior).
    if open_bins_count > 5 {
        score += (bin_residual as f64) * 0.2;
    }

    // 5. Dynamic time horizon: As the stream nears the end, become more aggressive 
    // about closing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Penalty for creating a bin with a residual significantly higher 
    // than the current mean, as it likely indicates poor packing efficiency.
    if post_residual > (mean_residual as u32 + 15) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" (residuals < 10 are generally unusable).
    // We increase score (penalize) as post_residual approaches small unusable values.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powf(1.5) * 2.0;
    }

    // Lookahead logic: If the next item is large, prioritize bins that can fit it.
    // If the current bin's post_residual is too small for the next item, penalize it.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.2) * 0.5;
    }

    // Dynamic thresholding: Near the end of the stream, prioritize aggressive packing (lower residuals).
    // Early in the stream, favor keeping bins open that have higher mean_residuals to accommodate future variance.
    let density_bias = (mean_residual - post) * (1.0 - progress);
    score -= density_bias * 0.8;

    // If this is the only bin that fits, we are forced to use it; lower the score to ensure it is picked.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New bin logic: If the current bin is empty (new bin candidate), 
    // only pick it if the penalty of filling existing bins is high (e.g., they result in very poor fit).
    if bin_residual == bin_capacity {
        // High penalty to open new bins unless existing bins are extremely inefficient.
        score = 40.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

