    // We penalize larger post_residuals heavily to keep bins packed tightly.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small (e.g., < 10), it is a "tight fit" which is generally good.
    // However, if post_residual is just slightly too small to fit common item sizes (e.g., 1-9),
    // it creates "dead space." We apply a penalty for post_residuals that are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
