    // 3. Lookahead Logic (Next Item Coupling):
    // If we have a next item, we want to ensure the post_residual can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: The next item will fit perfectly in this bin.
            score -= 40.0;
        } else {
            // Bad: The next item will force a new bin if we pick this one.
            score += 15.0;
        }
    }

    // 4. Threshold Logic:
    // If fitting_bins_count is 1, this is the only bin that can take the current item.
    // If we are considering a NEW bin (bin_residual == bin_capacity), we only open it
    // if the current bin's remaining space is extremely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can hold the item.
            score += 60.0;
        } else {
            // New bin is necessary.
            score -= 10.0;
        }
    }

    // 5. Global state normalization:
    // Use the mean_residual to balance the load across open bins.
    // If this bin is significantly emptier than the average, favor filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

