    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize new bin creation unless necessary
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        }
        return score;
    }

    // 2. Best-Fit logic: punish large post_residuals (wasted space)
    // We prefer post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead: if the next item is large, avoid splitting the current bin
    // if the resulting space is too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward keeping space for the next item
            score -= 15.0;
        }
    }

    // 4. Global state: encourage consolidation when few items remain
    if progress > 0.8 {
        score -= (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // 5. Criticality: If this is the last bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 6. Dynamic balance: penalize bins that deviate too far from the mean
    // This pushes the algorithm towards a "uniform" packing density.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps that are too small for common future items (the "fragmentation" penalty)
    // We penalize post_residuals that are small but not zero, as they are likely to remain unused.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * 2.5
    } else {
        0.0
    };

    // Factor in lookahead: if the next item fits better in this bin, prioritize this bin.
    let lookahead_penalty = if next_item_size > 0 && post >= next_item_size as f64 {
        -15.0 * (1.0 - progress)
    } else if next_item_size > 0 && post < next_item_size as f64 && post > 0.0 {
        10.0 * progress
    } else {
        0.0
    };

    // Balance between Best-Fit (low post) and keeping options open for later (high progress).
    // As the stream progresses, we become more aggressive about packing tightly.
    let base_score = post * (1.0 + 0.5 * progress);

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // heavily incentivize taking the fit to avoid opening a new bin.
    let desperation_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only open a new bin if the score is lower than existing bins.
    // We penalize opening a new bin heavily unless the open bins are very full.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 + (mean_residual * 0.5)) + (progress * 20.0)
    } else {
        0.0
    };

    base_score + fragmentation_penalty + lookahead_penalty + desperation_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1026: Harmonic Class Fitting
    // Strategy: Minimize post_residual while penalizing "fragmentation traps" 
    // where post_residual is too small to fit common upcoming items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Best-Fit: Prefer smaller post_residual (already in score)

    // 2. Lookahead Penalty: If post_residual is smaller than next_item_size, 
    // it creates dead space. If it is larger than next_item_size, it is a good candidate.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a hole that cannot fit the next expected item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it is often 
    // a "dead zone" (1-9). Penalize these specifically.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic Alignment: Reward states where the remaining space is a multiple 
    // of common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.2;

    // 5. Global Load Balancing: Avoid opening a new bin unless necessary.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High penalty to open new bin unless no other fitting bins are efficient.
        score += 40.0 + (open_bins_count as f64 * 2.0);

        // As we reach the end of the stream, prioritize closing bins.
        if progress > 0.9 {
            score -= 10.0;
        }
    } else {
        // Reward filling existing bins to keep fitting_bins_count high.
        score -= (fitting_bins_count as f64) * 0.5;
    }

    // 6. Mean Residual Correction: Avoid bins that deviate significantly from average.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
