    // This helps maintain a uniform distribution of fill-levels across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression weighting: As we approach the end of the stream, prioritize clearing existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space; we want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for leaving small, unusable gaps (1..9 range is usually dead space).
    // If post_residual is in (0, 10), it's a high-risk fragment.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is slightly less than next_item_size, it's a poor placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward: This bin can fit the next item perfectly.
        } else if post_residual > 0 {
            score += 15.0; // Penalty: This bin will likely not fit the next item.
        }
    }

    // 3. Global state balancing: Avoid opening new bins unnecessarily.
    // If we are forced to open a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the existing bins are all very crowded (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 4. Critical thresholding: If this is the only fitting bin, prioritize it to avoid
    // the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive
    // about consolidation (packing tightly to close bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead-zone" residuals (1-9)
    // that prevent future items from fitting. Reward bins that accommodate lookahead.

    let mut score = post_residual as f64;

    // 1. Dead-space penalty: If the remaining space is too small to fit typical items, 
    // it's effectively wasted. Penalize residuals in [1, 9].
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead utility: If a next item exists, favor bins that can accommodate it 
    // after the current item is placed.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // 3. Global Efficiency: If we are near the end of the stream, discourage opening new bins 
    // unless the fit is extremely poor.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream
        score += 30.0 + (progress * 20.0);
    }

    // 4. Density Balancing: If the current bin has a much higher residual than the mean, 
    // prioritize filling it to keep the "fill level" consistent across bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Critical Constraint: If this is the only bin that can fit the item, 
    // lower the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that prevent future fitting (fragmentation)
    // We want to avoid leaving gaps in the range (0, 15) which are hard to fill.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // Global efficiency: If we are late in the stream, prioritize tight fits (Best Fit).
    // If early, allow slightly looser packing to preserve bin diversity.
    let tightness_bias = (post * (1.0 - progress * 0.5)) * 0.5;

    // Favor bins that maintain the mean residual to keep packing density uniform.
    let deviation_penalty = (post - mean_residual).abs() * 0.3;

    // Penalty for opening a new bin when existing bins can fit the item.
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
        100.0 * (1.0 - progress * 0.2)
    } else {
        0.0
    };

    let mut score = post + fragmentation_penalty + lookahead_penalty + tightness_bias + deviation_penalty + new_bin_penalty;

    // Final scaling to ensure the new bin choice is only triggered when objectively superior.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize residuals in the (0, 10) range as they are effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is "sub-optimal" (large residual left over).
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open and the fit quality is poor,
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 35.0; // Penalize opening a new bin if an existing one works.
        } else {
            score -= 10.0; // Prefer opening a new bin if no other options exist.
        }
    } else {
        // Best-Fit logic: prioritize bins where the post_residual is minimized.
        // We add a slight penalty for having many open bins to encourage consolidation.
        score += (open_bins_count as f64) * 0.5;

        // Harmonic-style pressure: if the post_residual is close to the mean_residual, 
        // it suggests a balanced distribution of space.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is small (1-9), it is likely unusable.
    // Penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits in the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Bin Consolidation Pressure: If we have many open bins, penalize opening a new one 
    // or using a bin that keeps the mean_residual high/wasteful.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to existing open bins.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // If we are using an existing bin, reward configurations that bring 
        // the residual closer to the global mean (tight packing).
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Last Chance Logic: If this is the only bin that fits, prioritize it 
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Stream Progression: As the stream ends, be more aggressive about filling
    // remaining space to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to pack tightly, while using lookahead to avoid "orphaning" bins.
    let mut score = post_residual as f64;

