    // more aggressively (Best-Fit). If we have few, be more conservative.
    let density_penalty = (open_bins_count as f64) * 0.5;
    score += density_penalty;

    // 4. Fitting constraint: If this is the only bin that fits, prioritize it
    // heavily to avoid opening an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean residual equilibrium: penalize bins that deviate significantly
    // from the mean residual of open bins to encourage uniform packing.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

