}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize values close to 0 but > 0.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, we penalize it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic constraint: As the stream progresses, increase the cost of opening new bins
    // by penalizing empty bins (bin_residual == bin_capacity) proportionally to progress.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);

        // If there are other bins that could fit the item, strongly discourage opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with mean_residual: Favor bins that keep the overall average residual low,
    // but weigh this impact less as the stream finishes to allow for "cleanup" packing.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: Best-Fit Decreasing (BFD) variation with penalty for creating "fragmentation" 
    // that cannot accommodate the lookahead item.

    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0; // Strong penalty for opening a new bin prematurely
        } else {
            score -= 100.0; // Reward opening a new bin if nothing else fits
        }
    }

    // 2. Harmonic/Residual Optimization:
    // If we have a lookahead, penalize residual space that is smaller than the next item.
    // This reduces the chance of creating "dead space" that cannot be filled later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates a "useless" gap relative to the next item
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // This placement is "ideal" because it leaves room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global Packing Efficiency:
    // Favor bins that are already closer to being full (lower post_residual)
    // but balance this against the "mean_residual" to avoid clustering all 
    // small items into one bin and leaving large items stranded.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // 4. Progression adjustment:
    // As we approach the end of the stream, tighten the tolerance for gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is too small to fit any common item (e.g., < 10),
