    }

    // Discourage opening a new bin unless the current residual is truly suboptimal for the current item
    if bin_residual == bin_capacity {
        // New bin penalty scaled by how many bins are already open to prevent fragmentation
        score += 20.0 + (open_bins_count as f64 * 2.0);
    }

    // Factor in progress: as we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Penalty for creating a residual that is significantly lower than the mean residual (prevents imbalance)
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // If post_residual is in the range (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit logic: Strongly prefer bins where the item fits tightly.
    // We want post_residual to be small, but not in the "dead zone".
    // We reward post_residual values that are closer to 0 (excluding the 0-10 trap).
    if post_residual >= 10 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual,
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }

    // 4. Open Bins Pressure: Penalize opening a new bin if we have many bins open,
    // or reward it if we are desperate to empty a bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many open bins already.
        score += (open_bins_count as f64) * 15.0;

        // If we have very few open bins, opening a new one is less penalized.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    }

    // 5. Fitting Bins Count: If this is the only bin that can fit the item, 
    // force its selection to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Global density balance: If the current bin's residual is significantly 
    // higher than the mean, we prefer to fill it to normalize the state.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // 1. Base penalty: The tighter the fit (lower post_residual), the better.
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin:
    // If this is a new bin, we add a significant penalty unless it's the only option.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Lookahead Matching:
    // If the next item fits perfectly into this post_residual, we reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps after the next item is placed
        score -= (30.0 - diff).max(0.0);
    }

    // 4. Mean Residual Adaptation:
    // Avoid creating bins that deviate significantly from the current average residual.
    // This helps maintain a uniform packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Urgency factor:
    // If this is the last fitting bin, we are forced to use it; reward high-residual fits
    // slightly more than usual to avoid "trapping" large items in small gaps.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Progressive packing:
    // As the stream progresses, prioritize closing bins (lower post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
