    // but we adjust based on the next_item_size to leave room for potential future fits.
    let lookahead_penalty = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 // Reward bins that can accommodate the next item
        } else if post_residual > 0 && post_residual < 10 {
            20.0 // Penalize creating "dead space" that is too small for common items
        } else {
