    // Coupling: favor bins where the residual stays close to the mean, 
    // reducing variance in bin fullness.
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: prioritize lower post_residual (Best Fit), 
    // modulated by lookahead and stream-aware new-bin avoidance.
    post + new_bin_penalty + lookahead_penalty + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
