    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State: If we have many open bins, we should be more aggressive 
    // in filling existing ones rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress and open_bins_count.
        // As the process nears completion, opening a new bin is heavily discouraged.
        score += 30.0 + (open_bins_count as f64 * 2.0) + (progress * 50.0);
    } else {
        // Reward using existing bins, scaled by how much they deviate from the mean.
        // This encourages "leveling" the residuals of open bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Scarcity Penalty: If this is the only bin that can fit the item, 
    // treat it as a high-priority placement to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_r = post_residual as f64;
