        score += 40.0 * progress;

        // If we have other bins that could fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Interaction term: penalize opening new bins if we have many bins open already
    if bin_residual == bin_capacity {
