            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // If post_residual is too small for the next item, slight penalty
            score += 10.0;
        }
    }

    // 4. Global balance: Prefer bins close to the current mean_residual
    // This helps keep the distribution of remaining space uniform across bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
