            score += (next_item_size as f64 - post) * 10.0;
        }
    }

    // Encourage filling bins that are already "half-empty" to keep the mean_residual stable.
    // We compare current bin_residual to the global mean_residual.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * progress;

    // Favor bins that are the "last chance" (fitting_bins_count == 1) 
    // to keep the number of open bins low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual (already in score).
    // 2. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is in (0, 10), it is very hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Harmonic/Fractional Logic: Penalize bins that leave residuals which are not multiples of common item sizes.
    // We favor residuals that are 0, 20, 25, 33, 50 (divisors of 100).
    let rem = post_residual % 10;
    if rem != 0 {
        score += rem as f64 * 0.5;
    }

    // 5. New Bin Threshold: Discourage opening new bins unless the fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), set a base threshold.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // or if we have very few bins open.
        score += 45.0; 
        if open_bins_count > 0 && mean_residual < 20.0 {
            score += 30.0;
        }
    }

    // 6. Last chance logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 7. Progress scaling: As the stream nears the end, become more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // If post_residual is in the range [1, 9], it's highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when existing ones have capacity
    // If we are considering an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalize opening a new bin heavily if we have other options
            score += 45.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 3. Lookahead coupling: If next_item_size exists, favor bins that can accommodate it
    // If the current post_residual is smaller than the next item, we penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the current item, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 5. Mean residual balance: Avoid bins that deviate significantly from the mean
    // This helps keep packing density uniform across all bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progress factor: As we near the end of the stream, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that likely won't fit future items).
    // If post_residual is < 10, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins that leave space exactly matching the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward bins that have just enough room for the next item
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that cannot fit the next item when they could have
            score += 20.0;
        }
    }

    // 3. Global efficiency: If this is the only bin that fits the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. Balance: Avoid opening new bins unless necessary (penalty for new bin).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean residual alignment: Favor bins that keep the bin closer to the global average residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit Decreasing principle).
    // We want to minimize post_residual to pack bins tightly.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the existing fits are objectively poor (leaving large gaps).
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if items can fit elsewhere.
            // Penalty scales with how much space is already being wasted in active bins.
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no bins fit, new bin is mandatory; set score low.
            score = -100.0;
        }
    } else {
        // Lookahead heuristic: If the next item exists, reward bins that can accommodate 
        // both the current and the next item (synergy).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 30.0;
            } else {
                // If the next item won't fit, this bin is less desirable for the current item
                // if it leaves a "sliver" of space (e.g., 1-9 units) that is hard to fill.
                if post_residual < 10 {
                    score += 25.0;
                }
            }
        }

        // Dynamic thresholding: As we reach the end of the stream, prioritize 
        // closing bins (low residuals) over keeping many bins partially full.
        if progress > 0.8 {
            score += (open_bins_count as f64) * 5.0;
        }

        // Reward bins that bring the mean residual closer to a "tight" target (e.g., 10).
        // This keeps the bins balanced.
        let residual_diff = (post_residual as f64 - 10.0).abs();
        score += residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter packing (lower post_residual)
    let mut score = post * post;

    // Penalty for creating 'dead space' (bins that are very hard to fill later)
    // We penalize small residuals that are too small for common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post as f64) * 50.0;
    }

    // Lookahead: If next_item_size is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 150.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower open_bins_count)
    // We penalize opening new bins significantly more as the stream reaches the end
    if bin_residual == bin_capacity {
        score += 250.0 * progress;
        score += (open_bins_count as f64) * 20.0;
    } else {
        // If the bin is already open, favor bins that are closer to the mean_residual
        // to keep bin utilization balanced
        let deviation = (post as f64 - mean_residual).abs();
        score += deviation * 2.0;
    }

    // Critical constraint: If this is the only bin that fits, heavily incentivize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins that leave small residuals (best fit) 
    // unless the residual is very small (e.g., < 5), which creates "dead space".
    if post_residual < 5 {
        score += 15.0; 
    }

    // 2. Lookahead Logic: If the next item can fit in the post_residual, 
    // prioritize this bin to keep the packing tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Fragmentation Control: Penalize opening a new bin if other bins are available.
    // If the bin is new (bin_residual == bin_capacity), increase score to discourage 
    // opening a new bin unless existing options are extremely poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0;
    }

    // 4. Harmonic Alignment: Use modulo arithmetic to favor bin states that 
    // align with common item sizes (e.g., multiples of 20 or 25).
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 5. Global Efficiency: If the current bin's residual is significantly lower than the 
    // mean residual of all open bins, it is a high-performing bin. Reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Scarcity Penalty: If this is the only bin that can fit the item, 
    // reduce the score to ensure we use this bin rather than forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progression scaling: As we reach the end of the stream, prioritize 
    // closing bins (lower post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual values that are likely to become 
