    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If a next item exists, penalize bins that cannot 
    // accommodate the next item if the current fit leaves a gap that is too small.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, discourage opening a new one 
    // unless the fit is exceptionally poor (Best-Fit approach).
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only prefer if we have many open bins already or if the fitting options are poor.
        score += (open_bins_count as f64) * 2.0;
        if fitting_bins_count > 0 {
            score += 40.0; // Heavy penalty for opening new bin if existing ones fit
        }
    } else {
        // Favor bins that are already "tight" to keep others empty.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Progression scaling: As we reach the end of the stream, be more conservative 
    // with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
