    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that result in the smallest remaining gap.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If the current post_residual can accommodate the next item,
    // we heavily reward this bin to avoid opening a new one later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further discount if it fits perfectly (or near perfectly) for the next item.
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit any common item (e.g., < 10),
    // it is often "dead space". We penalize creating tiny gaps unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Open-Bin Pressure: If few bins can fit the item, we become more conservative
    // about opening new bins. If fitting_bins_count is 1, this is the last chance.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current mean_residual 
    // is already very low, suggesting we need more capacity.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0;
        } else {
            score += 80.0;
        }
    }

    // 6. Dynamic Scaling: As the stream progresses, prioritize closing bins 
    // to reduce total open bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual (the space left) is the base. Minimizing this is Best Fit.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (very small residuals that are hard to fill).
    // If post_residual is small but > 0, it's often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. New Bin Constraint: 
    // If bin_residual == bin_capacity, this is a request to open a new bin.
    // Heavily penalize opening a new bin if other bins could fit the current item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No other bin fits, so opening a new one is mandatory.
            score = 0.0;
        }
    }

    // 5. Balance residuals: Avoid bins that deviate significantly from the mean_residual.
    // This helps keep bins packed at similar levels.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize the new bin (bin_residual == bin_capacity) increasingly as the stream progresses
    // to discourage starting new bins late in the game.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (15.0 + (progress * 45.0)) * (1.0 + (open_bins_count as f64 * 0.1)) 
    } else { 
        0.0 
    };

    // Calculate a "Best Fit" baseline: lower post_residual is better.
    // We add a penalty for creating a "small" residual that is likely to be unusable (e.g., < 10).
    let fragmentation_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 - (post_res * 2.0)
    } else {
        0.0
    };

    // Incorporate lookahead: if next_item_size is large, avoid leaving a small residual.
    let lookahead_penalty = if next_item_size > 0 {
        let tightness = (post_res - next_item_size as f64).abs();
        if post_res < next_item_size as f64 {
            30.0 // Penalty for blocking the next item
        } else {
            tightness * 0.5
        }
    } else {
        0.0
    };

    // Reward bins that have residuals close to the current mean_residual,
    // encouraging consolidation of "fullness" across bins.
    let mean_alignment = (post_res - mean_residual).abs() * 0.2;

    // Final score: lower is better. 
    // We prefer low post_residual (Best Fit), but penalize fragmentation and bad lookahead.
    post_res + new_bin_penalty + fragmentation_penalty + lookahead_penalty + mean_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
