    // 4. Mean residual balancing: Prefer bins that keep the global average residual stable.
    // High mean_residual indicates we have many empty-ish bins; we prefer to fill those.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.5;

    // 5. Prefer tighter fits (Best Fit decreasing logic)
    score += (bin_capacity - post_residual) as f64 * 0.1;

