pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Prefer Best-Fit (small post_residual) but penalize creating "dead zones"
    // that are too small for common items (e.g., < 20), and use lookahead to reserve
    // space for the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": if the remaining space is small but 
    // too small for the next item or common small items, penalize it.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // 2. Lookahead optimization: If the next item fits into this post_residual, 
    // provide a significant bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    }

    // 3. Global state: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, it represents opening a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the item, 
    // prioritize it to avoid wasting space in other bins or force a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 5. Progression: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to minimize fragmentation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    // 6. Balance: If the post_residual is significantly lower than the mean_residual,
    // it means we are "tightening" the bin, which is generally good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for opening a new bin: if it's the new bin candidate (bin_residual == bin_capacity)
    // We scale this penalty by the progress; as the stream nears the end, we become
    // more aggressive in opening new bins to prevent stranded items.
    if bin_residual == bin_capacity {
        // High penalty to prevent creating new bins unless necessary
        // Reduces penalty as we approach the end of the stream (1.0 - progress)
        score += 45.0 * (1.0 - progress).powf(0.5);
    } else {
        // Optimization: If this is the only bin that fits, we should favor it
        // even if the post_residual is relatively high.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead heuristic: If the next item exists, penalize placements 
        // that create small "dead space" that cannot fit the next item.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 20.0 * (1.0 - (post_res / next_item_size as f64));
            }
        }
    }

    // Dynamic pressure: Penalize bins that deviate significantly from the mean_residual
    // to keep the fill levels uniform across open bins.
    let residual_diff = (post_res - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize keeping the residual small to maximize packing density.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If next_item_size fits in the post_residual,
    // reduce the score (reward this placement) to create a "combo" effect.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // or leave space for larger items (e.g., leaving exactly 20, 25, 33, 50).
    let harmonic_penalty = match post_residual {
        0 => -5.0,        // Perfect fit bonus
        r if r % 25 == 0 => -2.0,
        r if r % 20 == 0 => -1.5,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // 4. New Bin Threshold: If this is an empty bin, penalize it unless there are no good options.
    // We make it harder to open a new bin as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening a new bin proportional to available open bins
        score += 35.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // 5. Mean Residual Balancing: If the current bin is significantly better than the mean,
    // favor it to keep the "good" bins tight.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Last Chance Logic: If this is the only bin that fits the item, reward it to avoid
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
