}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become "dead space" (e.g., < 10)
    // We use a non-linear penalty that transitions as the bin fills up.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 / (post_residual as f64 + 1.0)
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size is large and fits current post_residual, 
    // prioritize keeping this bin open.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (next_item_size as f64 / 100.0)
    } else {
        0.0
    };

    // Discourage opening too many bins early, but be aggressive late-game.
    let bin_count_penalty = (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // Favor bins that align with the global mean residual to keep densities uniform.
    let density_alignment = (post as f64 - mean_residual).abs() * 0.1;

    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    // We increase the cost of opening a new bin as the stream progresses.
    let base_score = if bin_residual == bin_capacity {
        45.0 + (progress * 30.0)
    } else {
        post + dead_space_penalty + lookahead_bonus + density_alignment
    };

    base_score + bin_count_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
