    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (open_bins_count as f64 / (total_items as f64 / 10.0 + 1.0));
    }

    // Adaptive constraint: if this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Balance against mean_residual: prefer bins that are closer to the current average fullness.
    // This helps maintain a uniform distribution of residuals across bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that become as full as possible.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // strongly incentivize this bin to preserve the "tightness".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    }

    // 3. Last-Chance Mitigation: If this is the only bin that can fit the current item, 
    // we must take it, regardless of post_residual.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Global State Awareness: Avoid opening a new bin if the mean residual 
    // of existing bins is already tight.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin
        score += 40.0;
