    // We penalize larger residuals quadratically to prefer tighter packing.
    let mut score = post.powi(2);

    // Lookahead influence: If the next item fits better in the current post_residual,
    // lower the score to "save" this space for the next item.
    if next_item_size > 0 {
        let fit_diff = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
