    // about using open bins rather than opening new ones.
    // We penalize the "New Bin" candidate (bin_residual == bin_capacity) 
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 200.0 * (1.0 + progress * 2.0);
    }

    // Penalty for creating "dead zones": If the post_residual is small but 
    // not zero (e.g., < 10), it might be unusable for future large items.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - progress);
    }

    // Efficiency bias: If this is the only bin that can fit the item, 
    // reduce its score to prioritize consolidation.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // Interaction with mean_residual: If current bin is significantly 
    // worse than the average, penalize it.
    if post > mean_residual {
        score += (post - mean_residual) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
