pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as the stream progresses.
    // As progress approaches 1.0, we become more desperate to fit items into existing bins,
    // so we lower the penalty for small residuals.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res) * (1.0 - progress).powf(0.5) * 5.0
    } else {
        0.0
    };

    // Reward bins that have a residual close to the next item's size to minimize future fragmentation.
    // We only apply this if there is a lookahead item.
    let lookahead_reward = if next_item_size > 0 {
