    // If post_residual is small but > 0, it is often "dead space" (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead Coupling: 
    // If the next item is large, favor keeping space open.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize filling a bin if it prevents the next item from fitting here.
            score += 35.0;
        } else {
            // Reward if the next item fits perfectly into the remaining space.
            if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
                score -= 20.0;
            }
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless there are no other options or the bin is being forced.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strongly discourage opening a new bin if an existing one can take the item.
            score += 75.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Scaling:
    // As we approach the end of the stream, tighten the criteria to finish bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit the smallest possible 
    // future items (assuming a lower bound of ~10), we penalize it to avoid fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the current options are very poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on 
    // how many bins are already open and how much room is left in them.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0) + (100.0 - mean_residual);
    }

    // 3. Lookahead Optimization: If the next item is large, favor bins that leave enough room
    // to potentially fit that item later, or conversely, pack tightly if the next item is small.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that can't fit the next item if we have space to avoid that.
            score += 20.0;
        } else {
            // Reward keeping space for the next item.
            score -= 5.0;
        }
    }

    // 4. Scarcity Constraint: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more aggressive
    // about closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

