        score += (fitting_bins_count as f64) * 10.0;
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize tight packing (Best Fit) over lookahead
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

