pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit) while penalizing fragmentation
    // and using lookahead to keep space for larger upcoming items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize opening a new bin if an existing bin could fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0 + (progress * 20.0);
    }

    // 2. Fragmented space penalty: If post_residual is small but > 0, it's often wasted.
    // Small gaps (1-9) are hard to fill; prioritize leaving larger gaps or closing the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 3. Lookahead logic: If a next item exists, try to preserve space for it.
    // If next_item_size is large, avoid bins where post_residual would be too small for it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
