        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // 4. Global state adjustment: If open_bins_count is high, be more aggressive at filling 
    // current bins (Best Fit) to reduce the number of active bins.
    if (open_bins_count as f64) > (10.0 + (progress * 20.0)) {
        score -= (post_residual as f64) * 0.1;
    }

    // 5. Prefer bins that are already closer to being full (closer to mean_residual)
    // to keep the distribution of residuals tight.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.05;

    score
