pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) quadratically to favor tight packing.
    // However, reward keeping the residual high enough to fit the *next* item.
    let mut score = post * post * 0.01;

    // If this is a new bin, apply a penalty that decays as the stream progresses.
    // This forces tight packing early on and allows more flexibility near the end.
    if bin_residual == bin_capacity {
        score += 50.0 * (1.0 - progress).powf(0.5);
    }

    // Lookahead: If the next item cannot fit in this bin, penalize the residual
    // unless the residual is already near zero (perfect fit).
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Encourage filling bins that are already "below average" in terms of fullness
    // (i.e., bins with higher residuals).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score -= deviation * 0.2;

    // Penalize opening new bins if there are other fitting options, 
    // unless the current fit is exceptionally good (near zero post_residual).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residual values
    // We want to minimize the gap left behind.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes (e.g., 20, 25, 33).
    // This creates "clean" remaining space for future items.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.8;

    // 3. Next-Item Lookahead: If next_item_size is known, 
    // penalize placements that make it impossible to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 50.0;
        } else {
            // Reward if the post_residual is "tight" for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Thresholding: Avoid opening a new bin unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing bin could fit the item.
            score += 65.0;
        } else {
            // If no other bins fit, normalize the cost of opening a new bin.
            score = 40.0;
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, prioritize closing bins (lower residual)
    // to keep the number of open bins manageable.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
