        // Encourage Best-Fit behavior: prefer bins that result in smaller post_residual
        // but only if it's not in the "dead space" range.
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (small, unusable space).
    // If post_residual is small but not zero, it's often better to leave it larger.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - (post / 10.0));
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that leave a post_residual 
    // that is too small for the next item, unless it's a perfect fit.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += 25.0 * (1.0 - (post / next_item_size as f64));
        }
    }

    // Stream progression adjustment:
    // As the stream nears completion, become more aggressive about filling
    // existing bins to minimize the total bin count (higher weight on fitting_bins_count).
    let urgency = progress * 20.0;
    if fitting_bins_count > 0 {
        score -= urgency * (1.0 / fitting_bins_count as f64);
    }

    // Penalize opening a new bin (bin_residual == bin_capacity)
    // proportional to the number of existing bins and progress.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // Balancing: Favor bins that stay near the mean_residual to keep 
    // capacity distribution uniform across bins.
    let dev = (post - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
