    }

    // 4. Mean Residual Balancing:
    // Discourage creating bins that deviate significantly from the current average
    // residual to maintain a consistent packing density.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize aggressive packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
