    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space).
    // The base score is already post_residual, which favors tight fits.

    // 2. Lookahead Synergy: Reward bins where the remaining space can accommodate the next item.
    // If post_residual is >= next_item_size, we effectively "pre-fit" the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.85;
    }

    // 3. Fragmentation Avoidance: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Global Balance: If the current bin's residual is significantly above the mean, 
    // it's a good place to put large items to keep the mean low (Best Fit logic).
    // If it's below the mean, we preserve it for smaller items.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. New Bin Management: If evaluating an empty bin (bin_residual == bin_capacity),
    // heavily penalize it unless no other bin can fit the item or the remaining space is extremely tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 6. Progression Scaling: As the stream nears the end, be more aggressive about 
    // closing bins (favoring lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The goal is to minimize score.
    // Base score is the post_residual (Best Fit approach).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items).
    // If post_residual is < 10, it's likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual,
    // prioritize this bin to preserve bin capacity for other bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Dynamic adaptation: As the stream progresses, become more aggressive 
    // about filling bins (Best Fit) rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;

    // 4. If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless it's the only option or the current bins are nearly full.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we are late in the stream, penalize new bins even more to force compaction.
        score += progress * 30.0;
        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // 5. Global state: If the mean residual is high, we have many underutilized bins.
    // Penalize new bins if the current average is already high.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += 20.0;
    }

    // 6. Prefer bins that are already "tight" to keep open bins count low.
    // Reduce score if the bin is already well-utilized.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as we progress 
    // through the stream to force tighter packing in the early/mid stages.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Best-Fit Decreasing logic: favor small post_residual (tightest fit).
    // Use a quadratic penalty for large post_residuals to heavily discourage "loose" fits.
    let fit_score = post.powi(2) / 10.0;

    // Lookahead coupling: if the next item is large, penalize small residuals that 
    // would have been better served by saving space for the next item.
    let lookahead_penalty = if next_item_size > 0 {
        let space_needed = next_item_size as f64;
        if post < space_needed && post > 0.0 {
            // Penalize cutting off the ability to fit the next item
            (space_needed - post) * 2.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Entropy control: penalize opening too many bins if the current bin is already 
    // reasonably efficient, but allow it if we are at the very end of the stream.
    let density_pressure = (open_bins_count as f64 - (1.0 - progress) * 10.0).max(0.0) * 2.0;

    score = fit_score + new_bin_penalty + lookahead_penalty + density_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize small residuals that cannot accommodate typical item sizes
    // We target "dead space" by penalizing post_residuals in the range (0, 10) as they are likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fragmentation Control: Penalize opening new bins if there are existing fitting options.
    // If this is a new bin (bin_residual == bin_capacity) and we have fitting bins, heavily penalize it.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 50.0 * (fitting_bins_count as f64).sqrt();
    }

    // 4. Harmonic Alignment: Favor placements that leave residuals which are multiples of common item sizes (e.g., 20, 25, 50).
    // This helps pack future items of similar classes.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    // 5. Global Density: If the mean residual is high, we are being too loose; tighten up.
    // If mean_residual is low, we are constrained; be more flexible with new bin openings.
    if mean_residual < 20.0 {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // 6. Progress Weighting: Near the end of the stream, prioritize fitting into existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps
    // (dead space < 10, which is the minimum item size) and manage bin proliferation.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps smaller than the smallest possible item).
    // If post_residual is in (0, 10), it's highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // bins are already open to discourage fragmenting items into too many bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 1.5);
    }

    // Lookahead logic: if the next item could fit into this specific post_residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Pressure to consolidate: if there are many open bins, increase the cost of opening
    // a new one or choosing a bin that leaves a large residual.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a structural penalty based on current efficiency
    if bin_residual == bin_capacity {
        // Only open new if we are forced or if the mean residual is already too tight
        // Penalize opening a new bin if other bins exist
        score += (open_bins_count as f64 * 15.0) + (mean_residual * 0.5);
    } else {
        // 2. Best-fit logic with lookahead penalty
        // Penalty for creating "dead zones" where the next item won't fit
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Severe penalty for stranding the next item
                score += 50.0;
            } else {
                // Reward placements that leave exactly enough for the next item (perfect fit)
                let diff = (post_residual - next_item_size) as f64;
                score -= 20.0 / (1.0 + diff);
            }
        }

        // 3. Prevent fragmentation: penalize if this is the only fitting bin but it's a poor fit
        if fitting_bins_count == 1 && post_residual > 20 {
            score += 10.0;
        }

        // 4. Tightness bias: favor bins that are already closer to the mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Progression scaling: become more aggressive as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
