    // If post_residual is small (e.g., < 10), it is likely to remain unused for the rest of the stream.
    // We heavily penalize creating gaps between 1 and 9.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
