        // High penalty to prevent opening new bins unnecessarily if others can fit the item.
        score += (open_bins_count as f64 * 5.0) + (20.0 * (fitting_bins_count as f64));
    } else {
        // Encourage using existing bins that have a residual close to the mean_residual
        // to keep bin utilization uniform.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 4. Progression scaling:
    // As we near the end of the stream, prioritize closing bins (lower scores for higher utilization)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
