    // 5. Progression Weighting: As the stream nears the end, prioritize closing bins
    // over maintaining strict best-fit, to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
