    // 2. Harmonic Penalty: Heavily penalize post_residuals that are small but unusable (e.g., 1..9)
    //    since item sizes are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
