    // 3. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter fits for the lookahead item
        score -= (post_residual - next_item_size) as f64 * 0.2;
