    // 4. Threshold Control: If this is the only bin that fits the current item, 
    //    force selection by heavily reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Suppression: Make opening a new bin expensive unless it is the only option,
    //    or if the current open bins have very low mean_residual (high fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
