pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bin opening based on progress: 
    // As the stream nears the end, opening new bins becomes increasingly expensive.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 45.0 + 5.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: favor small post_residual, 
    // but penalize post_residual values that are too small to fit common upcoming items.
    // If next_item_size is large, small post_residuals are "dead space" traps.
    let dead_space_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
