    };

    // Coupling: If fitting_bins_count is 1, we are at a "critical" bin.
    // We should be more selective to avoid fragmenting the bin if a better fit 
    // could be found later or if it leaves a gap too small for the mean residual.
    let criticality = if fitting_bins_count == 1 && !is_new_bin { -10.0 } else { 0.0 };

    // Base score is the post_residual itself (Best-Fit principle).
    // We adjust by non-linear factors to balance global packing efficiency.
    let score = post 
        + new_bin_penalty 
        + dead_space_penalty 
        + criticality 
        + (post / (mean_residual + 1.0)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1291: Harmonic-Residual Balancing
    // We prioritize Best-Fit (minimizing post_residual) but penalize "fragmentation" 
    // where the post_residual is too small to accommodate common subsequent items 
    // or creates a bin that is difficult to fill later.

