    score += progress * (open_bins_count as f64 * 0.5);

    // Reward bins that are closer to the mean residual to keep bin fill 
    // levels balanced (reduces variance, keeps more bins available).
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but prioritize fits that leave space 
