    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals 
    // to keep bins tightly packed.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If post_residual can accommodate the next item, 
