        }
    }

    // 4. Balance the distribution: penalize bins that deviate too far 
    // from the mean residual of current open bins to keep utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression scaling: as we approach the end of the stream, 
    // prioritize tighter fits more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "fragmented" small residuals (Best-Fit principle)
    // We heavily penalize residuals that are too small to fit common items (e.g., < 15).
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead optimization
    // If the next item exists, penalize placements that leave too little room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty if we block the next item from fitting in this bin.
            score += 60.0;
        } else {
            // Reward if we leave just enough room for the next item (tight packing).
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 / (1.0 + slack as f64));
        }
    }

    // 3. Global state balancing
    // If we have many open bins, prioritize closing them (Best-Fit).
    // If we are near the end of the stream, be more aggressive with space utilization.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * density_factor * progress;
    }

    // 4. New Bin Logic
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless all other options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 55.0;

        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -1000.0;
        } else {
            // Make new bin increasingly attractive as the stream progresses 
            // if current bins are very fragmented (high mean_residual).
            score += mean_residual * 0.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

