    }

    // 5. New Bin Threshold:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only choose it if the penalty of existing bins is extremely high.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the 
        // current fitting options are all extremely poor.
        score += (open_bins_count as f64) * 2.5;

        // Dynamic scaling based on stream progress
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the mean residual to keep
    // bin utilization uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
