            // Must open a new bin, base score is neutral.
            score = 10.0;
        } else {
            // Penalize opening a new bin if we could have fit it elsewhere.
            // This penalty decreases as we approach the end to avoid fragmentation.
            score = 100.0 * (1.0 - (progress * 0.5));
        }
    } else {
        // Favor bins that have less remaining space (Best Fit variant)
        // Subtract to reward tighter packing.
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Final adjustment based on fitting_bins_count
    // If this is the last chance to fit the item into an existing bin, reduce the score.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit strategy)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bins
    // We want to be more conservative about opening new bins as the stream progresses
    if is_new_bin {
        score += 25.0 + (progress * 40.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward for tighter fits that leave little room for future items
        // Non-linear coupling: penalize residuals that are too large, especially if next_item_size is large
        let waste_penalty = (post_residual as f64).powf(1.5);
        score += waste_penalty * 0.1;

        // Lookahead: If next_item_size is large, penalize bins that would make it impossible to fit
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }

        // Favor bins that align with the current mean_residual to keep bin distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Heuristic: If this is the last chance to fit the item in existing bins, 
    // heavily penalize the new-bin option to force reuse.
    if fitting_bins_count == 1 && is_new_bin {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining gaps (dead space)
    // We favor post_residuals that are small (tight fit) or large enough to fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward fits that leave room for the lookahead item
            score -= (next_item_size as f64) * 1.5;
        } else {
            // Penalize creating a bin that cannot accommodate the next item
            score += (bin_capacity - post_residual) as f64 * 0.5;
        }
    }

    // 2. Harmonic Class Logic:
    // If the residual is in a range that is "useless" (e.g., < 10), penalize heavily.
    if post_residual < 10 {
        score += 50.0;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), evaluate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is poor across all open bins.
        // We normalize the open bin count to ensure we don't open too many bins early.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
    }

    // 4. Fitting Bin Scarcity:
    // If this is the only bin that fits the item, make it highly attractive (low score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual alignment:
    // Penalize bins that deviate too far from the average state of existing bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #1357: Strict Dead Space Avoidance & Adaptive Open Bin Pressure
    // Objective: Minimize post_residual while penalizing "unusable" gaps (1..9) 
    // and using open_bins_count to dampen new bin creation.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the "unusable" range (1-9),
    // it is highly likely to be wasted. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // reward this placement to maximize bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: If this is a new bin (bin_residual == bin_capacity),
    // penalize based on open_bins_count. Avoid opening new bins if existing
    // bins have sufficient capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have many bins open, penalize the new bin even more to force
        // reuse of existing bins.
        if open_bins_count > 5 {
            score += 20.0;
        }
    } else {
        // 4. Fitting Constraint: If this is the last bin that can fit the item,
        // prioritize it to keep the "new bin" threshold high.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Global Efficiency: If the current bin is significantly emptier than the mean,
    // prefer filling it to bring it closer to the global average residual.
    let residual_delta = (bin_residual as f64) - mean_residual;
    if residual_delta > 0.0 {
        score -= residual_delta * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best-Fit principle).
    // If post_residual is 0, this is a perfect fit.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to the next_item_size, we favor this bin.
    // We reward bins that leave exactly enough (or slightly more) space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + slack);
    }

    // 3. Fragmentation Mitigation: Penalize creating "dead space" that is too small for any item (e.g., < 10).
    // If post_residual is small but not zero, it's often a "wasted" sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global Load Balancing: Avoid opening too many bins if the current bin is already well-utilized.
    // If we are about to open a new bin, penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage opening a new bin if an existing bin can fit the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Mean Residual Alignment: If this bin's post_residual is significantly better than the global mean, 
    // it helps keep the packing density high across the set.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progress-based refinement: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
